def _lire_reglage_allegement():
    """Lit l'interrupteur UNE SEULE FOIS, au lancement (zero jeton, zero appel API).
    Le fichier est cree s'il n'existe pas. Si la lecture rate, on allege quand meme : un souci
    de fichier ne doit JAMAIS empecher Luciana de travailler."""
    try:
        if os.path.isfile(FICHIER_REGLAGE_ALLEGEMENT):
            with open(FICHIER_REGLAGE_ALLEGEMENT, encoding="utf-8-sig") as f:
                return bool((json.load(f) or {}).get("allegement_actif", True))
    except Exception:
        return True
    try:
        with open(FICHIER_REGLAGE_ALLEGEMENT, "w", encoding="utf-8") as f:
            json.dump({"allegement_actif": True, "_a_quoi_ca_sert": _EXPLICATION_REGLAGE},
                      f, ensure_ascii=False, indent=2)
    except Exception:
        pass
    return True


