def _dossiers_prives():
    h = os.path.expanduser("~")
    return [os.path.join(HOME, "Luciana_navigateur"), os.path.join(h, ".grok"), os.path.join(h, ".claude"),
            os.path.join(h, ".ssh"), os.path.join(h, ".config", "gh")]


def _dans(chemin, dossier):
    try:
        c, d = os.path.normcase(os.path.realpath(chemin)), os.path.normcase(os.path.realpath(dossier))
        return c == d or c.startswith(d.rstrip("\\/") + os.sep)
    except Exception:
        return False


def _fichier_secret(chemin):
    """Rend la raison si ce fichier ne doit JAMAIS sortir du PC, sinon ''."""
    if not chemin:
        return ""
    base = os.path.basename(str(chemin)).lower()
    for fin in (".precedent", ".tmp"):
        if base.endswith(fin):
            base = base[:-len(fin)]
    if base in _SECRETS and _dans(chemin, DOSSIER):
        return "c'est un fichier secret de Luciana (cle, mot de passe ou autorisation)"
    if base.startswith("luciana_memoire_") and base.endswith(".zip"):
        return "c'est une sauvegarde complete de Luciana (elle contient ses cles et mots de passe)"
    for d in _dossiers_prives():
        if _dans(chemin, d):
            return "c'est un dossier prive de connexion (sessions, cles)"
    return ""


def _refus_secret(chemins):
    for c in chemins or []:
        r = _fichier_secret(c)
        if r:
            return ("Je ne le fais pas : %s ne sort jamais de ton PC (%s). Tes secrets restent chez toi, "
                    "c'est une protection du programme." % (os.path.basename(str(c)), r))
    return ""


def _garder_precedent(chemin):
    """Avant chaque ecriture, on garde la version actuelle (si elle est saine) en '.precedent'."""
    try:
        if os.path.exists(chemin):
            with open(chemin, "r", encoding="utf-8") as f:
                json.load(f)
            shutil.copy2(chemin, chemin + ".precedent")
    except Exception:
        pass


# ---------- v76 : LES ANCIENNES VERSIONS DU CARNET ET DES SOUVENIRS ----------
# Le carnet de chantier etait REECRIT EN ENTIER a chaque mise a jour : tout detail non recopie
# disparaissait pour toujours. C'est exactement comme ca que le prix du PC de la cliente Daniela
# (2500 lei, la machine plus chere qu'ELLE avait choisie) a ete perdu, puis confondu avec le prix
# de reference du business. Maintenant, avant de remplacer, on garde l'ancienne version en entier
# dans un fichier DATE, a cote, et on peut la RELIRE (outil 'anciennes_notes').
DOSSIER_ANCIENNES_NOTES = os.path.join(DOSSIER, "anciennes_notes")
ANCIENNES_NOTES_GARDEES = 1250     # minuscule en place prise, et ca couvre des mois de travail


def _archiver_note(chemin, quoi):
    """Garde l'etat ACTUEL du fichier dans anciennes_notes/<quoi>/<quoi>_AAAA-MM-JJ_HHhMM-SS.json,
    AVANT qu'il soit remplace. Rend le chemin garde, ou '' si rien n'a pu etre garde."""
    try:
        if not os.path.exists(chemin):
            return ""
        with open(chemin, "r", encoding="utf-8") as f:
            contenu = f.read()
        json.loads(contenu)                     # on n'archive jamais un fichier abime
        dest = os.path.join(DOSSIER_ANCIENNES_NOTES, quoi)
        os.makedirs(dest, exist_ok=True)
        p = os.path.join(dest, "%s_%s.json" % (quoi, time.strftime("%Y-%m-%d_%Hh%M-%S")))
        if os.path.exists(p):                   # deux ecritures dans la meme seconde
            p = p[:-5] + "-2.json"
        with open(p, "w", encoding="utf-8") as f:
            f.write(contenu)
        gardes = sorted(x for x in os.listdir(dest) if x.endswith(".json"))
        for vieux in gardes[:-ANCIENNES_NOTES_GARDEES]:
            try:
                os.remove(os.path.join(dest, vieux))
            except OSError:
                pass
        return p
    except Exception:
        return ""


def _versions_anciennes(quoi):
    """La liste des anciennes versions gardees, de la plus recente a la plus ancienne."""
    dest = os.path.join(DOSSIER_ANCIENNES_NOTES, quoi)
    try:
        return sorted((x for x in os.listdir(dest) if x.endswith(".json")), reverse=True)
    except Exception:
        return []


def _charger_version_ancienne(quoi, nom):
    chemin = os.path.join(DOSSIER_ANCIENNES_NOTES, quoi, nom)
    try:
        with open(chemin, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None


def _quand_version(nom):
    """'carnet_2026-09-30_18h04-12.json' -> '2026-09-30 18h04'."""
    m = re.search(r"(\d{4}-\d{2}-\d{2})_(\d{2})h(\d{2})", nom or "")
    return "%s %sh%s" % (m.group(1), m.group(2), m.group(3)) if m else (nom or "?")


def sauvegarde_du_jour():
    """Une copie par jour de la memoire, des souvenirs, du carnet et des comptes, dans
    ~/Luciana/sauvegardes/AAAA-MM-JJ/. On garde les 60 derniers jours."""
    try:
        jour = time.strftime("%Y-%m-%d")
        dest = os.path.join(DOSSIER_SAUVEGARDES, jour)
        os.makedirs(dest, exist_ok=True)
        for nom in _FICHIERS_A_SAUVEGARDER:
            src = os.path.join(DOSSIER, nom)
            if os.path.exists(src) and not os.path.exists(os.path.join(dest, nom)):
                try:
                    with open(src, "r", encoding="utf-8") as f:
                        json.load(f)  # on ne sauvegarde pas un fichier abime par-dessus un bon
                    shutil.copy2(src, os.path.join(dest, nom))
                except Exception:
                    pass
        jours = sorted(d for d in os.listdir(DOSSIER_SAUVEGARDES) if os.path.isdir(os.path.join(DOSSIER_SAUVEGARDES, d)))
        for vieux in jours[:-60]:
            shutil.rmtree(os.path.join(DOSSIER_SAUVEGARDES, vieux), ignore_errors=True)
    except Exception:
        pass


def charger_memoire():
    return _charger_json_sur(FICHIER_MEMOIRE, [])


def sauver_memoire(messages):
    # Ecriture sure : on ecrit d'abord un fichier temporaire, puis on le renomme.
    # Comme ca, meme une coupure de courant ne peut pas abimer la memoire.
    # (Aucun plafond : on garde TOUT l'historique, on ne perd jamais rien.)
    _garder_precedent(FICHIER_MEMOIRE)
    tmp = FICHIER_MEMOIRE + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(messages, f, ensure_ascii=False, indent=2)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, FICHIER_MEMOIRE)


def ajouter_a_la_memoire(message_utilisateur, texte_reponse, actions=None, note_lignes=None):
    """Ajoute l'echange (toi + elle) a la memoire, de facon SURE meme si le PC et le
    telephone parlent en meme temps : on relit la memoire fraiche et on ajoute a la fin.
    On note aussi la date et les outils VRAIMENT utilises (avec leur resultat reel), pour
    qu'elle sache au message suivant ce qu'elle a fait pour de vrai (pas juste ce qu'elle a dit)."""
    date = time.strftime("%Y-%m-%d %H:%M")
    sauvegarde_du_jour()
    with _verrou_memoire:
        frais = charger_memoire()
        moi = {"role": "user", "content": message_utilisateur, "date": date}
        if note_lignes:
            moi["note_lignes"] = list(note_lignes)   # v88 : mises a jour du carnet/souvenirs, chacune EN ENTIER
        frais.append(moi)
        rep = {"role": "assistant", "content": texte_reponse, "date": date}
        if actions:
            rep["actions"] = actions
        frais.append(rep)
        sauver_memoire(frais)


def ajouter_note_memoire(texte):
    """Ajoute une note de Luciana dans la memoire (ex : le rapport d'un chantier Claude Code fini),
    pour qu'elle le retrouve au message suivant au lieu de l'oublier."""
    with _verrou_memoire:
        frais = charger_memoire()
        frais.append({"role": "assistant", "content": texte, "date": time.strftime("%Y-%m-%d %H:%M")})
        sauver_memoire(frais)


# ---------- FENETRE "LA JOURNEE ENTIERE" + RAPPEL AUTOMATIQUE ----------
VEILLE_GARDEE = 50              # messages d'avant aujourd'hui gardes sous les yeux (fin de la veille)
# =====================================================================
#  BUDGET_FENETRE — A TRAITER A PART, ET FRED L'A DEMANDE EXPRES (13/10/2026).
#
#  CE N'EST PAS UN PLAFOND DE MEMOIRE, et il ne RESTREINT PAS la memoire de Fred.
#  C'EST LA TAILLE PHYSIQUE DE LA FENETRE DU CERVEAU. Le modele n'accepte qu'une
#  certaine quantite de texte dans UN appel ; au-dela, l'appel est REFUSE et Luciana ne
#  repond pas du tout. Ce nombre n'est donc pas un choix de Fred : c'est un mur qui
#  existe en dehors du programme, et ce garde-fou sert juste a ne pas s'y cogner.
#
#  CE QU'IL FAIT QUAND IL JOUE, ET C'EST RARE : il fait avancer le DEBUT de la fenetre
#  par paquets de 50 messages. IL N'EFFACE RIEN : les messages qui sortent de la fenetre
#  restent entiers dans luciana_memoire.json, et le programme va les rechercher tout
#  seul par le sens quand Fred en parle.
#
#  POURQUOI IL EST RAREMENT ATTEINT : le rangement du fil se declenche a SEUIL_JOURNEE
#  (80 000 car.) et redescend a CIBLE_APRES_RANGEMENT (50 000 car.). Le fil envoye au
#  cerveau reste donc normalement entre 50 000 et 80 000 caracteres -- six a dix fois
#  sous ce garde-fou. Il ne sert qu'au cas tordu : un seul message enorme, du genre un
#  document de 400 000 caracteres colle d'un coup.
#
#  DECISION, ET ELLE EST DITE : ON N'Y TOUCHE PAS. Le baisser couperait des
#  conversations pour rien ; le monter ferait rater l'appel et Luciana se taira. Il est
#  en CARACTERES dans le code, et le commentaire d'origine l'annoncait en jetons (~150 000
#  jetons, soit a peu pres 500 000 caracteres de francais) : les deux unites sont
#  maintenant ecrites noir sur blanc, pour qu'on ne les confonde plus.
# =====================================================================
BUDGET_FENETRE = 500000         # EN CARACTERES (~150 000 jetons). Mur du modele, pas un
                                # plafond de memoire : rien n'est efface. Voir ci-dessus.
PAQUET_FENETRE = 50             # si le garde-fou joue, la fenetre avance par gros paquets (rarement)


PAUSE_NOUVELLE_JOURNEE = 5 * 3600   # une "journee de travail" commence apres une pause de 5 h ou plus QUI CONTIENT LA NUIT


def _heure_msg(m):
    try:
        return time.mktime(time.strptime(str(m.get("date"))[:16], "%Y-%m-%d %H:%M"))
    except Exception:
        return None


def _pause_de_nuit(avant, apres):
    """Vrai si entre ces deux moments il y a une vraie nuit : au moins 5 h, et 4 h du matin dedans."""
    if apres - avant < PAUSE_NOUVELLE_JOURNEE:
        return False
    t = time.localtime(avant)
    quatre = time.mktime((t.tm_year, t.tm_mon, t.tm_mday, 4, 0, 0, 0, 0, -1))
    if quatre <= avant:
        quatre += 24 * 3600
    return quatre <= apres


def _debut_journee(hist):
    """Index du 1er message de la journee de travail en cours : celui qui suit la derniere NUIT de pause.
    Travailler apres minuit ne coupe plus la journee (avant, a minuit, elle 'oubliait' la soiree), et une
    longue pause dans la journee (ex. 10 h -> 17 h) ne la coupe pas non plus."""
    suivant = time.time()
    for i in range(len(hist) - 1, -1, -1):
        t = _heure_msg(hist[i])
        if t is None:
            if i == len(hist) - 1:
                continue            # le message qu'on vient de recevoir (pas encore date)
            return i + 1
        if _pause_de_nuit(t, suivant):
            return i + 1
        suivant = min(suivant, t)
    return 0


# =====================================================================
#  LE RANGEMENT AUTOMATIQUE DE LA JOURNEE DANS LA BIBLIOTHEQUE
#  (consigne de chantier preparee par Fred le 05/10/2026)
#  PREMIERE PARTIE : les chiffres de Fred, la MESURE JUSTE, et le carnet de rangement.
#  (La deuxieme partie -- le rangement lui-meme -- est plus bas, juste avant repondre().)
#
#  CE QUI N'ALLAIT PAS, MESURE CHEZ FRED LE 05/10/2026 A 22h51 (releve, pas devine) :
#    - 476 messages dans la journee, 832 804 caracteres ;
#    - 241 245 caracteres partaient au cerveau a CHAQUE appel ;
#    - le garde-fou de 200 000 (BUDGET_FENETRE) a coupe la fenetre 7 a 8 fois dans la journee, et
#      chaque coupe recharge TOUT le cache (~0,75 a 0,95 $ la coupe).
#  DEUX DEFAUTS, PAS UN SEUL :
#    (1) la memoire de la journee est la seule memoire SANS TRI : elle ne fait que grossir ;
#    (2) LA MESURE ETAIT FAUSSE. _debut_fenetre ne comptait que m["content"], alors que repondre()
#        ajoute a chaque message son JOURNAL D'OUTILS et ses NOTES DE MEMOIRE avant de l'envoyer.
#        C'est pour ca que 241 245 caracteres sont partis avec un garde-fou regle sur 200 000.
#        _taille_reelle_message() ci-dessous compte ce qui part VRAIMENT.
#  CE QU'ON FAIT (decide par Fred) : PYTHON OBLIGE, LUCIANA CHOISIT LES TIROIRS, PYTHON RANGE ET
#  RAMENE. Au-dela de SEUIL_JOURNEE, le programme fait ranger la journee dans la bibliotheque qui
#  existe DEJA (~/Luciana/bibliotheque, creee le 02/10 par la v89), par vrais sujets, d'un bon coup,
#  jusqu'a redescendre a CIBLE_APRES_RANGEMENT.
#  CE QUI N'EST JAMAIS TOUCHE : luciana_memoire.json reste COMPLET, mot pour mot, jamais reecrit ni
#  raccourci. On note seulement A PART, dans journee_rangee.json, quels messages sont ranges et ou.
#  Le garde-fou de 200 000 RESTE, en dernier secours seulement.
#  L'INTERRUPTEUR : reglage_rangement_journee.json, a cote du programme (comme reglage_voyants.json).
#  "rangement_journee_actif": false -> on retrouve EXACTEMENT la v110, l'ancienne mesure comprise.
# =====================================================================
FICHIER_REGLAGE_RANGEMENT = os.path.join(DOSSIER_PROG, "reglage_rangement_journee.json")

# LES CHIFFRES DECIDES PAR FRED (consigne du 05/10/2026, RELEVES PAR FRED LE 06/10/2026).
# AVANT : 80 000 et 20 000. Le rangement partait trop tot et descendait trop bas : la journee etait
# videe dans la bibliotheque alors que Fred en avait encore besoin dans la conversation.
# 13/10/2026 : CES DEUX LIGNES SONT MONTEES ICI, de 40 lignes plus bas, pour une seule raison --
# le texte d'explication juste en dessous doit pouvoir LIRE les vrais chiffres au lieu de les
# recopier a la main. C'est comme ca qu'il annoncait 150 000 et 70 000 alors que le programme
# appliquait 80 000 et 50 000 : un chiffre recopie finit toujours par mentir.
SEUIL_JOURNEE = 80000            # au-dela, le rangement se declenche (obligatoire)
CIBLE_APRES_RANGEMENT = 50000     # on range d'un bon coup, jusqu'a redescendre a 50 000 car. (v162)

# 13/10/2026 (05h07, ordre de Fred) : LE FIL GARDE, C'EST 80 000 / 50 000 CARACTERES, RIEN
# D'AUTRE. Le compte en messages a ete supprime en v162, et c'est VOULU : on ne le remet PAS.
