def _lire_reglage_sens():
    """Lu UNE fois au lancement (comme les autres reglage_*.json). Cree s'il manque. Au moindre
    pepin : les valeurs par defaut (sens allume).
    v131 : les reglages ajoutes (budget_carnets_nommes, dossier_sujet_messages) sont lus avec un
    .get() a defaut, donc un ANCIEN fichier reglage_memoire_sens.json (qui ne les contient pas)
    continue de marcher sans rien changer : il prend les valeurs du code."""
    defaut = {"actif": True, "seuil": 0.40, "budget_bibliotheque": BIBLIOTHEQUE_SENS_BUDGET,
              "ecart_relatif": SENS_ECART_RELATIF,
              "budget_carnets_nommes": CARNETS_NOMMES_BUDGET,
              "dossier_sujet_messages": DOSSIER_SUJET_MESSAGES_MAX,
              "bibliothecaire_par_etiquettes": True,
              "bibliothecaire_decrochage": BIBLIOTHECAIRE_DECROCHAGE,
              "bibliothecaire_ecart": BIBLIOTHECAIRE_ECART,
              "bibliothecaire_plancher": BIBLIOTHECAIRE_PLANCHER}
    try:
        if os.path.isfile(FICHIER_REGLAGE_SENS):
            with open(FICHIER_REGLAGE_SENS, encoding="utf-8-sig") as f:
                d = json.load(f) or {}
            return {"actif": bool(d.get("actif", True)),
                    "seuil": float(d.get("seuil", defaut["seuil"])),
                    "budget_bibliotheque": int(d.get("budget_bibliotheque", BIBLIOTHEQUE_SENS_BUDGET)),
                    "ecart_relatif": float(d.get("ecart_relatif", SENS_ECART_RELATIF)),
                    "budget_carnets_nommes": int(d.get("budget_carnets_nommes", CARNETS_NOMMES_BUDGET)),
                    "dossier_sujet_messages": int(d.get("dossier_sujet_messages", DOSSIER_SUJET_MESSAGES_MAX)),
                    # v134 : lus avec un .get() a defaut -- un ANCIEN reglage_memoire_sens.json (qui
                    # ne les contient pas) continue donc de marcher, et le bibliothecaire est allume.
                    "bibliothecaire_par_etiquettes": bool(d.get("bibliothecaire_par_etiquettes", True)),
                    "bibliothecaire_decrochage": float(d.get("bibliothecaire_decrochage", BIBLIOTHECAIRE_DECROCHAGE)),
                    "bibliothecaire_ecart": float(d.get("bibliothecaire_ecart", BIBLIOTHECAIRE_ECART)),
                    "bibliothecaire_plancher": int(d.get("bibliothecaire_plancher", BIBLIOTHECAIRE_PLANCHER))}
    except Exception:
        return defaut
    try:
        with open(FICHIER_REGLAGE_SENS, "w", encoding="utf-8") as f:
            json.dump(dict(defaut, _a_quoi_ca_sert=_EXPLICATION_REGLAGE_SENS), f,
                      ensure_ascii=False, indent=2)
    except Exception:
        pass
    return defaut


