def _pendant_oui(valeur, defaut=True):
    """Lit un oui/non ecrit a la main par Fred, sans jamais se plaindre. Ce qu'on ne reconnait
    pas rend le defaut : un reglage mal ecrit ne doit pas eteindre une piece en silence."""
    if valeur is None:
        return defaut
    if isinstance(valeur, bool):
        return valeur
    t = str(valeur).strip().lower()
    if t in ("0", "non", "no", "false", "off", "eteint", "eteinte", "arret", "arrete"):
        return False
    if t in ("1", "oui", "yes", "true", "on", "marche", "allume", "allumee"):
        return True
    return defaut


def _pendant_ecrire_reglage(d):
    """Ecrit le reglage proprement (fichier temporaire puis remplacement, flush + fsync).
    Appele seulement a la toute premiere creation du fichier.
    Rend (Vrai, '') ou (Faux, la raison). Ne leve jamais."""
    try:
        os.makedirs(os.path.dirname(FICHIER_REGLAGE_PENDANT) or ".", exist_ok=True)
        tmp = FICHIER_REGLAGE_PENDANT + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, FICHIER_REGLAGE_PENDANT)
        return True, ""
    except Exception as ex:
        return False, str(ex)[:300]


def _pendant_reglage():
    """Le reglage, relu SUR LE DISQUE a chaque appel : quelques octets, zero jeton, zero appel
    API, et le choix de Fred prend effet tout de suite. Le fichier est cree s'il manque.
    Ne leve jamais."""
    d = {}
    try:
        if os.path.isfile(FICHIER_REGLAGE_PENDANT):
            with open(FICHIER_REGLAGE_PENDANT, encoding="utf-8-sig") as f:
                d = json.load(f) or {}
        else:
            d = {"marche": True, "les_mots": True, "l_arret": True,
                 "_a_quoi_ca_sert": _EXPLICATION_REGLAGE_PENDANT}
            _pendant_ecrire_reglage(d)
    except Exception:
        d = {}
    if not isinstance(d, dict):
        d = {}
    marche = _pendant_oui(d.get("marche"))
    return {"marche": marche,
            "les_mots": bool(marche and _pendant_oui(d.get("les_mots"))),
            "l_arret": bool(marche and _pendant_oui(d.get("l_arret")))}


