#  (1) LA FILE DE MOTS : UN JOURNAL QUI NE FAIT QUE S'AJOUTER
# ---------------------------------------------------------------------
def _pendant_ajouter_ligne(chemin, enregistrement):
    """AJOUTE une ligne au journal, et rend Vrai SEULEMENT si l'ecriture a vraiment abouti sur
    le disque (flush + fsync). On n'ouvre JAMAIS en mode 'w' : un journal ne se reecrit pas,
    donc rien ne peut y disparaitre. Rend Faux au moindre pepin -- et c'est ce Faux qui, plus
    bas, empeche un mot de Fred d'etre perdu en silence."""
    try:
        os.makedirs(os.path.dirname(chemin) or ".", exist_ok=True)
        with open(chemin, "a", encoding="utf-8") as f:
            f.write(json.dumps(enregistrement, ensure_ascii=False) + "\n")
            f.flush()
            os.fsync(f.fileno())
        return True
    except Exception:
        return False


def _pendant_lire_les_lignes():
    """Toutes les lignes de la file, dans l'ordre ou elles ont ete ecrites. Une ligne illisible
    est SAUTEE, jamais corrigee et jamais effacee : on prefere sauter une ligne abimee que
    reecrire le fichier. Rend [] si la file n'existe pas : ce n'est pas une panne, c'est une
    file vide. Ne leve jamais."""
    lignes = []
    try:
        if not os.path.isfile(FICHIER_MOTS_EN_ROUTE):
            return lignes
        with open(FICHIER_MOTS_EN_ROUTE, encoding="utf-8-sig", errors="replace") as f:
            for brut in f:
                brut = brut.strip()
                if not brut:
                    continue
                try:
                    d = json.loads(brut)
                except Exception:
                    continue
                if isinstance(d, dict):
                    lignes.append(d)
    except Exception:
        return lignes
    return lignes


def mots_en_route_en_attente():
    """CE QUI ATTEND D'ETRE LU, REJOUE a partir de la file (jamais stocke a part, donc jamais
    faux) : une ligne 'mot' entre, une ligne 'lu' la sort. Le plus ancien d'abord.
    AUCUNE ECRITURE ICI. Ne leve jamais."""
    try:
        lignes = _pendant_lire_les_lignes()
        deja_lus = set()
        for d in lignes:
            if str(d.get("quoi") or "") == "lu":
                try:
                    deja_lus.add(int(d.get("numero") or 0))
                except Exception:
                    pass
        attente = []
        for d in lignes:
            if str(d.get("quoi") or "") != "mot":
                continue
            try:
                n = int(d.get("numero") or 0)
            except Exception:
                continue
            if n in deja_lus:
                continue
            if not str(d.get("texte") or "").strip():
                continue
            attente.append(d)
        return attente
    except Exception:
        return []


def mot_en_route_deposer(texte):
    """LA PIECE 1. Fred glisse un mot PENDANT qu'elle travaille.

    CETTE FONCTION N'APPELLE NI repondre() NI _verrou_tour, ET C'EST TOUT L'INTERET : elle ne
    fait qu'ajouter une ligne dans un journal, puis elle rend la main. Elle ne peut donc pas
    attendre la fin du tour, meme si le tour dure cinq minutes.
    Rend (Vrai/Faux, la phrase a afficher a Fred, combien de mots attendent). Ne leve jamais."""
    mot = str(texte or "").strip()
    if not mot:
        return False, "Tu ne m'as rien ecrit : je n'ai rien mis dans la file.", 0
    if not pendant_les_mots_marchent():
        return False, ("L'interrupteur est ETEINT dans %s : je n'ai rien depose, et je te le dis "
                       "plutot que de faire semblant." % FICHIER_REGLAGE_PENDANT), 0
    coupe = False
    if len(mot) > PENDANT_MOT_MAX:
        mot = mot[:PENDANT_MOT_MAX]
        coupe = True
    en_plein_travail = _un_tour_est_en_cours()
    with _verrou_pendant:
        numero = 0
        for d in _pendant_lire_les_lignes():
            try:
                numero = max(numero, int(d.get("numero") or 0))
            except Exception:
                pass
        numero += 1
        ecrite = _pendant_ajouter_ligne(FICHIER_MOTS_EN_ROUTE, {
            "quoi": "mot", "numero": numero,
            "date": time.strftime("%Y-%m-%dT%H:%M:%S"), "quand": time.strftime("%Hh%M"),
            "texte": mot, "coupe": coupe, "pendant_un_travail": bool(en_plein_travail),
            "version": "V176"})
        combien = len(mots_en_route_en_attente()) if ecrite else 0
    if not ecrite:
        return False, ("Je n'ai PAS pu ecrire ton mot dans %s. Je te le dis franchement plutot "
                       "que de le perdre en silence : redis-le moi." % FICHIER_MOTS_EN_ROUTE), 0
    if en_plein_travail:
        phrase = ("C'est dans la file (mot n%d). Je le lis a ma prochaine pause d'outil, sans "
                  "attendre la fin de mon travail." % numero)
    else:
        phrase = ("C'est dans la file (mot n%d) -- mais je ne travaille pas en ce moment : il "
                  "sera lu a mon prochain travail. Pour me parler tout de suite, parle-moi "
                  "normalement." % numero)
    if coupe:
        phrase += (" (Ton mot etait tres long : je n'ai garde que ses %d premiers caracteres.)"
                   % PENDANT_MOT_MAX)
    if combien >= PENDANT_BEAUCOUP:
        phrase += " (Attention : %d mots attendent deja d'etre lus.)" % combien
    return True, phrase, combien


# ---------------------------------------------------------------------
#  (3) L'ARRET : UN DRAPEAU SUR LE DISQUE, ET AUCUN FIL TUE
# ---------------------------------------------------------------------
class ArretDemandeParFred(Exception):
    """Levee par un point de controle quand Fred a demande l'arret. CE N'EST PAS UNE PANNE :
    elle est attrapee a UN SEUL endroit, repondre(), JUSTE AVANT le 'except Exception' qui note
    les echecs -- et c'est pour ca qu'un arret n'est jamais ecrit en memoire comme une panne, et
    qu'il ne touche pas au compteur 'pas repondu'.
    AUCUN FIL N'EST TUE : c'est le tour lui-meme qui se range, a un endroit ou le programme sait
    exactement ou il en est."""

    def __init__(self, ou=""):
        Exception.__init__(self, "arrete par Fred (%s)" % (ou or "en route"))
        self.ou = str(ou or "")


# Ce qu'on met dans les 'tool_result' des outils qui n'ont PAS tourne. Honnete : rien n'a ete fait.
ARRET_TOOL_RESULT = ("ARRET demande par Fred : cet outil n'a PAS ete lance. Rien n'a ete fait "
                     "de ce cote.")

PHRASE_ARRET_POUR_FRED = (
    "Je me suis arretee, tu me l'as demande. Je n'ai PAS fini : ce qui etait deja fait est fait, "
    "le reste n'a pas ete lance. Dis-moi ce qu'on fait maintenant.")


def arret_demander():
    """LA PIECE 3, cote clic de Fred. Pose le DRAPEAU, et rien d'autre.

    CETTE FONCTION N'APPELLE NI repondre() NI _verrou_tour, ET ELLE NE TUE AUCUN FIL : elle
    ecrit un fichier de quelques octets, puis elle rend la main. C'est le tour en cours qui lira
    le drapeau a son prochain point de controle et qui se rangera tout seul.
    SI AUCUN TRAVAIL N'EST EN COURS, ON NE POSE RIEN : sinon le drapeau resterait la et
    couperait le PROCHAIN message de Fred, pour rien.
    Rend (Vrai/Faux, la phrase a afficher). Ne leve jamais."""
    if not pendant_l_arret_marche():
        return False, ("L'interrupteur d'arret est ETEINT dans %s : je n'ai rien fait, et je te "
                       "le dis plutot que de faire semblant." % FICHIER_REGLAGE_PENDANT)
    if not _un_tour_est_en_cours():
        return False, ("Je ne travaille pas en ce moment : il n'y a rien a arreter. (Je n'ai pose "
                       "aucun drapeau, comme ca ton prochain message ne sera pas coupe pour rien.)")
    try:
        with _verrou_pendant:
            os.makedirs(os.path.dirname(FICHIER_ARRET_DEMANDE) or ".", exist_ok=True)
            tmp = FICHIER_ARRET_DEMANDE + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump({"arret": True, "date": time.strftime("%Y-%m-%dT%H:%M:%S"),
                           "quand": time.strftime("%Hh%M"), "version": "V176"},
                          f, ensure_ascii=False, indent=1)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp, FICHIER_ARRET_DEMANDE)
    except Exception as ex:
        return False, ("Je n'ai PAS pu poser le drapeau d'arret (%s). Je te le dis franchement : "
                       "je ne me suis donc PAS arretee." % str(ex)[:200])
    return True, ("C'est note : je m'arrete a mon prochain point de controle (avant mon prochain "
                  "appel, ou avant mon prochain outil). Quelques secondes au plus.")


def _arret_demande():
    """Vrai si le drapeau est pose. Lecture de quelques octets : zero jeton, zero appel API.
    SI LE FICHIER EXISTE MAIS QU'IL EST ILLISIBLE, ON REPOND VRAI : entre ignorer un clic de
    Fred et arreter un travail pour rien, on choisit d'obeir a Fred. (Et le drapeau est de toute
    facon enleve au debut de chaque tour, donc un fichier abime ne peut pas bloquer la suite.)
    Ne leve jamais."""
    try:
        if not pendant_l_arret_marche():
            return False
        if not os.path.isfile(FICHIER_ARRET_DEMANDE):
            return False
        try:
            with open(FICHIER_ARRET_DEMANDE, encoding="utf-8-sig") as f:
                d = json.load(f) or {}
        except Exception:
            return True
        if not isinstance(d, dict):
            return True
        return bool(d.get("arret"))
    except Exception:
        return False


def _arret_oublier():
    """Enleve le drapeau. Appele au DEBUT de chaque tour -- mais DANS le verrou du tour, jamais
    avant : si on l'enlevait avant de prendre le verrou, un deuxieme message en train d'attendre
    effacerait l'arret que Fred vient de demander pour le tour en cours, et son clic serait
    perdu. Appele aussi juste apres un arret. Ne leve jamais."""
    try:
        if os.path.isfile(FICHIER_ARRET_DEMANDE):
            os.remove(FICHIER_ARRET_DEMANDE)
        return True
    except Exception:
        return False


def _arret_completer_les_tool_result(reponse, resultats, messages):
    """LE RISQUE N4 DU RAPPORT D'ANALYSE, BOUCHE ICI.

    L'API d'Anthropic exige que CHAQUE bloc 'tool_use' d'une reponse ait son 'tool_result' dans
    le message suivant. Si on s'arrete au milieu des outils, il en manque : la conversation est
    invalide et l'appel suivant serait REFUSE. On fabrique donc le resultat manquant de chaque
    outil qui n'a pas tourne -- "arrete par Fred, pas lance", c'est-a-dire la verite -- et on
    pose le tout dans 'messages'.
    Rend le nombre de resultats fabriques. Ne touche a rien si tout est deja complet, et ne leve
    jamais : ce menage ne doit en aucun cas empecher l'arret de Fred."""
    try:
        if reponse is None or resultats is None or messages is None:
            return 0
        deja = set()
        for r in resultats:
            try:
                deja.add(r.get("tool_use_id"))
            except Exception:
                pass
        ajoutes = 0
        for bloc in (getattr(reponse, "content", None) or []):
            if getattr(bloc, "type", "") != "tool_use":
                continue
            bid = getattr(bloc, "id", None)
            if bid in deja:
                continue
            resultats.append({"type": "tool_result", "tool_use_id": bid,
                              "content": ARRET_TOOL_RESULT})
            ajoutes += 1
        if resultats:
            messages.append({"role": "user", "content": list(resultats)})
        return ajoutes
    except Exception:
        return 0


def _arret_si_fred_a_dit_stop(ou, reponse=None, resultats=None, messages=None):
    """LE POINT DE CONTROLE. Pose a trois endroits : avant chaque appel au cerveau, avant chaque
    outil, et entre deux gestes a l'ecran.
    IL NE COUTE RIEN : la lecture d'un petit fichier. Zero jeton, zero appel API.
    QUAND FRED N'A RIEN DEMANDE, IL NE FAIT RIEN DU TOUT, et le travail continue exactement
    comme avant la V176. Quand Fred a clique, il complete d'abord les 'tool_result' manquants
    (pour ne pas laisser une conversation invalide derriere nous), puis il leve
    ArretDemandeParFred."""
    if not _arret_demande():
        return False
    _arret_completer_les_tool_result(reponse, resultats, messages)
    raise ArretDemandeParFred(ou)


def _arret_le_tour_est_fini(message_utilisateur, image, stop):
    """Ce que le programme fait apres un arret demande par Fred, et c'est TOUT ce qu'il fait :
      - il enleve le drapeau (sinon le message suivant de Fred serait coupe pour rien) ;
      - il ecrit dans la memoire que CE message a ete ARRETE PAR FRED. Noir sur blanc : jamais
        maquille en panne, jamais maquille en reponse reussie ;
      - il NE TOUCHE PAS au compteur 'pas repondu' (compteur_pas_repondu.json). Ce chiffre
        compte les fois ou elle est passee a cote, pas les fois ou FRED a appuye sur le bouton.
        Le gonfler ici serait une fausse mesure, et Fred s'en sert pour juger ;
      - il NE TUE AUCUN FIL : on est deja sorti du travail proprement, tout seul.
    Le 'finally' de repondre() fait ensuite son travail habituel (_tour_termine).
    Rend la phrase affichee a Fred. Ne leve jamais."""
    _arret_oublier()
    ou = getattr(stop, "ou", "") or "en route"
    try:
        texte = message_utilisateur or ("[photo envoyee par Fred]" if image else "")
        if texte:
            ajouter_a_la_memoire(texte,
                                 "[Le programme : ARRETE PAR FRED (%s). Le travail a ete "
                                 "interrompu a sa demande. Ce qui etait deja fait est fait ; le "
                                 "reste n'a pas ete lance. Ce n'est PAS une panne, et ce n'est "
                                 "PAS une reponse a cote.]" % ou)
    except Exception:
        pass
    return PHRASE_ARRET_POUR_FRED
# ==== V176 FIN DU BLOC ====


def _petit_cache_poser_lot(couples, vecteurs):
    """Range TOUT UN LOT d'empreintes d'un coup dans le petit cache.

    v164 — QUAND LE CACHE EST PLEIN, ON NE LE VIDE PLUS. AVANT : passe 50 000 empreintes, le code
    faisait un clear() TOTAL puis recalculait TOUT dans le message de Fred (plusieurs minutes, en
    plein tour). MAINTENANT : on fait la place AVANT de poser, en jetant les plus anciennes (les
    dict Python gardent l'ordre d'arrivee), et jamais celles qu'on vient de calculer. Ce qui est
    paye une fois n'est donc jamais jete dans la foulee. Ne leve jamais."""
    try:
        couples = list(couples)
        besoin = len(_SENS_PETIT_CACHE) + len(couples) - SENS_PETIT_CACHE_PLAFOND
        if besoin > 0:
            # on jette au moins la moitie : sinon on referait ce menage a chaque message
            a_jeter = min(len(_SENS_PETIT_CACHE), max(besoin, SENS_PETIT_CACHE_PLAFOND // 2))
            for k in list(_SENS_PETIT_CACHE.keys())[:a_jeter]:
                _SENS_PETIT_CACHE.pop(k, None)
        for (h, _b), v in zip(couples, vecteurs):
            _SENS_PETIT_CACHE[h] = v
    except Exception:
        pass


def _petit_cache_charger():
    """Relit le petit cache ecrit sur le disque au lancement precedent. v164 : c'est CE QUI FAIT
    QU'UN REDEMARRAGE NE COUTE PLUS 10 A 30 MINUTES. Si les deux fichiers ne se correspondent pas,
    on repart de rien : c'est un cache, il se refera. Ne leve jamais."""
    try:
        import numpy as np
        dim = int(_SENS.get("dim") or 0)
        if dim <= 0:
            return 0
        with open(FICHIER_SENS_CACHE_CLES, encoding="utf-8") as f:
            cles = [l.strip() for l in f if l.strip()]
        if not cles:
            return 0
        vect = np.fromfile(FICHIER_SENS_CACHE_VECTEURS, dtype="float16")
        lignes = min(len(cles), len(vect) // dim)
        if lignes <= 0:
            return 0
        vect = vect[:lignes * dim].reshape(lignes, dim).astype("float32")
        for i in range(lignes):
            _SENS_PETIT_CACHE[cles[i]] = vect[i]
        return lignes
    except Exception:
        return 0


_SENS_CACHE_ECRIT = {"combien": 0, "quand": 0.0}


def _petit_cache_sauver(force=False):
    """Ecrit le petit cache sur le disque (fichier temporaire puis remplacement d'un coup, comme
    tout le reste). Appele par le FIL DE FOND seulement, jamais dans le tour de Fred. Ne leve
    jamais : un cache qui ne s'ecrit pas ne doit casser aucune reponse."""
    try:
        import numpy as np
        maintenant = time.monotonic()
        combien = len(_SENS_PETIT_CACHE)
        if not combien:
            return 0
        if not force:
            # on n'ecrit que si ca a vraiment bouge, et jamais plus d'une fois par minute
            if combien < _SENS_CACHE_ECRIT["combien"] + 200:
                return 0
            if maintenant - float(_SENS_CACHE_ECRIT["quand"] or 0.0) < 60:
                return 0
        os.makedirs(DOSSIER_SENS, exist_ok=True)
        couples = list(_SENS_PETIT_CACHE.items())
        tmp = FICHIER_SENS_CACHE_VECTEURS + ".tmp"
        np.asarray([v for _h, v in couples], dtype="float32").astype("float16").tofile(tmp)
        os.replace(tmp, FICHIER_SENS_CACHE_VECTEURS)
        tmp = FICHIER_SENS_CACHE_CLES + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            f.write("\n".join(h for h, _v in couples))
        os.replace(tmp, FICHIER_SENS_CACHE_CLES)
        _SENS_CACHE_ECRIT.update(combien=len(couples), quand=maintenant)
        return len(couples)
    except Exception:
        return 0


class _MoteurFastembed:
    """Le vrai moteur : fastembed (ONNX, sans le gros paquet torch), modele multilingue.
    Signatures lues dans le code de fastembed : TextEmbedding(model_name, cache_dir).embed(textes)
    rend un generateur de vecteurs numpy."""
    def __init__(self):
        fe = _module("fastembed")
        os.makedirs(DOSSIER_SENS_MODELE, exist_ok=True)
        self.m = fe.TextEmbedding(model_name=SENS_MODELE, cache_dir=DOSSIER_SENS_MODELE)

    def vecteurs(self, textes):
        import numpy as np
        return np.array([np.asarray(v, dtype="float32") for v in self.m.embed(list(textes))],
                        dtype="float32")


def sens_pret():
    """Vrai seulement si le moteur est charge ET l'interrupteur allume."""
    return bool(REGLAGE_SENS.get("actif")) and _SENS["moteur"] is not None


_SENS_DERNIERES_PHRASES = {}    # la phrase de Fred sert 5 fois par message : calculee une seule fois


def _sens_vecteurs(textes):
    """Empreintes normalisees (longueur 1) : la ressemblance = un simple produit scalaire."""
    import numpy as np
    textes = [str(t or " ")[:4000] for t in textes]
    if len(textes) == 1 and textes[0] in _SENS_DERNIERES_PHRASES:
        return _SENS_DERNIERES_PHRASES[textes[0]]
    if not textes:
        return np.zeros((0, max(1, _SENS["dim"] or 1)), dtype="float32")
    v = np.asarray(_SENS["moteur"].vecteurs(textes), dtype="float32")
    n = np.linalg.norm(v, axis=1, keepdims=True)
    n[n == 0] = 1.0
    v = v / n
    if len(textes) == 1:
        if len(_SENS_DERNIERES_PHRASES) > 8:
            _SENS_DERNIERES_PHRASES.clear()
        _SENS_DERNIERES_PHRASES[textes[0]] = v
    return v


def _decouper(texte, maxi=SENS_MORCEAU):
    """Coupe un texte en passages d'au plus 'maxi' caracteres, sur un blanc. Rien n'est perdu :
    les passages mis bout a bout redonnent tout le texte."""
    texte = str(texte or "").strip()
    morceaux = []
    while len(texte) > maxi:
        coupe = texte[:maxi]
        blanc = max(coupe.rfind("\n"), coupe.rfind(" "))
        if blanc < maxi // 2:
            blanc = maxi
        morceaux.append(texte[:blanc].strip())
        texte = texte[blanc:].strip()
    if texte:
        morceaux.append(texte)
    return morceaux


# =====================================================================
#  13/10/2026 — TRAVAIL 1 DU CHANTIER « LA BIBLIOTHEQUE 2 COMME FRED LA VEUT » :
#  PLUS AUCUN PLAFOND QUI COUPE LA FIN D'UNE FICHE.
#
#  LE DEFAUT, LU PAR FRED DANS LE CODE : trois endroits faisaient « _decouper(t)[:40] ».
#  Un passage fait au plus SENS_MORCEAU caracteres (700), donc 700 x 40 = 28 000 : au-dela,
#  la fin d'une fiche n'etait JAMAIS mesuree par le sens. Le texte restait bien sur le
#  disque, mais il devenait introuvable -- EN SILENCE, rien a l'ecran ne le disait.
#
#  LA REPARATION, QUI EXISTAIT DEJA ET QUI EST EPROUVEE : c'est mot pour mot celle de
#  biblio2_bibliothecaire._morceaux(). On ne jette pas les passages au-dela du 40e :
#  ON ELARGIT les passages (on double leur taille) jusqu'a ce que TOUT le texte tienne
#  dans 40 passages. Le NOMBRE de passages reste donc exactement le meme qu'avant --
#  le moteur de sens travaille autant et pas plus, LA VITESSE NE CHANGE PAS -- mais il
#  n'y a plus un seul caractere hors de la mesure.
#
#  SENS_MORCEAU (700) N'EST PAS TOUCHE : c'est la taille de DEPART d'un passage, et elle
#  reste celle d'aujourd'hui pour tout ce qui tient dans 40 passages (la quasi-totalite
#  des fiches, qui sortent donc EXACTEMENT les memes morceaux et les memes scores
#  qu'avant). Elle ne s'elargit que pour les fiches tres longues, celles qui etaient
#  justement coupees.
#
#  ====================================================================================
#   ET ATTENTION, UN QUATRIEME PLAFOND SE CACHAIT JUSTE A COTE, DANS LE MEME TUYAU.
#  ====================================================================================
#   _sens_vecteurs(), quelques lignes au-dessus, fait « str(t)[:4000] » sur CHAQUE texte
#   avant de calculer son empreinte. Si on elargissait les passages sans limite, un
#   passage de 5 600 caracteres serait donc RE-COUPE a 4 000 au moment de la mesure, et on
#   aurait remis exactement la faute qu'on vient d'enlever -- en silence, une fois de plus.
#
#   ON ELARGIT DONC JUSQU'A 4 000 ET PAS AU-DELA, et quand 40 passages de 4 000 ne
#   suffisent pas (une fiche de plus de 160 000 caracteres), ON REND PLUS DE PASSAGES AU
#   LIEU DE PERDRE LA FIN. C'est la regle de Fred appliquee telle quelle : « ON NE COUPE
#   PAS : ON DECOUPE. » Mesurer un peu plus longtemps vaut mieux qu'un bout de memoire
#   introuvable, et ca ne concerne de toute facon qu'une poignee de fiches geantes.
#
#   A DIRE FRANCHEMENT, PARCE QUE C'EST VRAI : le modele de sens lui-meme
#   (paraphrase-multilingual-MiniLM) ne regarde qu'un DEBUT de texte -- quelques centaines
#   de caracteres. Un passage de 700 est donc lu en entier par le modele, un passage de
#   4 000 ne l'est pas vraiment. C'est pour ca qu'on part de 700 et qu'on ne s'elargit QUE
#   pour les fiches geantes : pour elles, une mesure approximative de la fin vaut infiniment
#   mieux que l'ancienne situation, ou cette fin n'etait pas mesuree DU TOUT.
# =====================================================================
SENS_MORCEAUX_PAR_FICHE_MAXI = 40   # le nombre de passages mesures par fiche (inchange)
# Le plafond que _sens_vecteurs applique de son cote : on ne fabrique jamais un passage plus
# long que ca, sinon il serait re-coupe au moment de la mesure et on reperdrait sa fin.
SENS_MORCEAU_MESURABLE_MAXI = 4000


def _decouper_sans_rien_perdre(texte, maxi=SENS_MORCEAU, combien_maxi=None):
    """LES PASSAGES D'UN TEXTE POUR LA MESURE DU SENS, SANS EN PERDRE UN SEUL CARACTERE.

    Remplace « _decouper(texte)[:combien_maxi] », qui jetait la fin en silence. Ici, quand
    il faudrait plus de 'combien_maxi' passages, on ELARGIT les passages au lieu d'enlever
    la fin -- jusqu'a SENS_MORCEAU_MESURABLE_MAXI, le plafond au-dela duquel _sens_vecteurs
    re-couperait. Et si meme ca ne suffit pas, on rend TOUS les passages : plus de passages,
    jamais un bout de texte hors de la mesure.

    Pour tout ce qui tient dans 'combien_maxi' passages de 'maxi' -- c'est-a-dire la
    quasi-totalite des fiches -- CETTE FONCTION REND EXACTEMENT CE QUE RENDAIT
    « _decouper(texte)[:40] », passage pour passage : memes empreintes, memes scores, meme
    vitesse. Ne leve JAMAIS : au moindre pepin, on rend le decoupage simple."""
    try:
        texte = str(texte or "").strip()
        if not texte:
            return []
        maxi = max(50, int(maxi or SENS_MORCEAU))
        combien_maxi = max(1, int(combien_maxi or SENS_MORCEAUX_PAR_FICHE_MAXI))
        morceaux = _decouper(texte, maxi)
        while len(morceaux) > combien_maxi and maxi < SENS_MORCEAU_MESURABLE_MAXI:
            maxi = min(SENS_MORCEAU_MESURABLE_MAXI, maxi * 2)
            morceaux = _decouper(texte, maxi)
        return morceaux or [texte]
    except Exception:
        try:
            return _decouper(texte)
        except Exception:
            return []


def _controle_sens(ligne):
    """Le chien de garde ECRIT ICI, jamais a l'ecran de Fred. Ne leve jamais."""
    try:
        ligne = dict(ligne)
        ligne.setdefault("quand", time.strftime("%Y-%m-%d %H:%M:%S"))
        with open(FICHIER_CONTROLE_SENS, "a", encoding="utf-8") as f:
            f.write(json.dumps(ligne, ensure_ascii=False) + "\n")
    except Exception:
        pass


# ---------- LE GRAND TIROIR (index des conversations et des resultats d'outils) ----------
def _empreinte_message(m):
    import hashlib
    c = m.get("content") if isinstance(m, dict) else m
    return hashlib.sha1(str(c).encode("utf-8", "replace")).hexdigest()


def _sens_charger_index():
    """Relit l'index du disque. Il se tient toujours : si les deux fichiers ne sont pas de la
    meme longueur (coupure de courant), on garde la partie commune."""
    import numpy as np
    etat = _charger_json_sur(FICHIER_SENS_ETAT, None) or {}
    if etat.get("modele") != SENS_MODELE or int(etat.get("dim") or 0) != _SENS["dim"]:
        return False
    morceaux = []
    try:
        with open(FICHIER_SENS_MORCEAUX, encoding="utf-8") as f:
            for ligne in f:
                try:
                    morceaux.append(json.loads(ligne))
                except Exception:
                    break
        vect = np.fromfile(FICHIER_SENS_VECTEURS, dtype="float16")
    except Exception:
        return False
    dim = _SENS["dim"]
    lignes = min(len(morceaux), len(vect) // dim)
    abime = lignes != len(morceaux) or lignes * dim != len(vect)
    conv, outils = int(etat.get("conv") or 0), int(etat.get("outils") or 0)
    # Coupure de courant entre l'ajout des passages et l'ecriture de l'etat : des passages
    # au-dela de ce que l'etat annonce. On les retire (ils seront reindexes, sans doublon).
    garder = [i for i in range(lignes)
              if int(morceaux[i]["n"]) < (conv if morceaux[i].get("s") == "conv" else outils)]
    if len(garder) != lignes:
        abime = True
    morceaux = [morceaux[i] for i in garder]
    vect = vect[:lignes * dim].reshape(lignes, dim)[garder].astype("float32")
    with _verrou_sens:
        _SENS.update(morceaux=morceaux, conv=conv, outils=outils,
                     empreinte=str(etat.get("empreinte") or ""))
        _sens_poser_reserve(vect)        # v164 : la place d'avance, au lieu d'une recopie par paquet
        _sens_refaire_par_message()
    if abime:
        _sens_reecrire_tout()
    return True


def _sens_poser_reserve(vect):
    """v164 — LA PLACE RESERVEE D'AVANCE. AVANT : chaque paquet de 256 passages faisait un
    np.vstack, c'est-a-dire une RECOPIE DE TOUT L'INDEX (73 693 x 384 nombres = 113 Mo) juste pour
    ajouter 256 lignes. MAINTENANT : on reserve de la place d'avance (8 192 passages de marge, soit
    plusieurs jours) et on ecrit DEDANS ; quand la marge est epuisee, on reserve a nouveau. Une
    recopie tous les 8 192 passages au lieu d'une toutes les 256.
    _SENS["vecteurs"] reste EXACTEMENT ce qu'il etait : la partie utilisee, lue telle quelle par
    sens_chercher. Appele sous _verrou_sens."""
    import numpy as np
    dim = int(_SENS.get("dim") or 0) or (int(vect.shape[1]) if vect is not None and len(vect) else 1)
    n = 0 if vect is None else int(len(vect))
    # Une marge raisonnable : de quoi tenir des jours sans rien recopier, sans gaspiller la memoire
    # vive (on ne double pas : 73 000 passages x 384 nombres, ca compte).
    capacite = max(1024, n + 8192)
    reserve = np.zeros((capacite, dim), dtype="float32")
    if n:
        reserve[:n] = vect
    _SENS["reserve"] = reserve
    _SENS["vecteurs"] = reserve[:n]


def _sens_place_pour(combien):
    """Fait de la place pour 'combien' passages de plus dans la reserve (en reservant a nouveau,
    avec sa marge, si elle est epuisee). Rend (reserve, deja). Appele sous _verrou_sens."""
    import numpy as np
    dim = int(_SENS.get("dim") or 0) or 1
    reserve = _SENS.get("reserve")
    deja = 0 if _SENS.get("vecteurs") is None else int(len(_SENS["vecteurs"]))
    if reserve is None or reserve.shape[1] != dim:
        _sens_poser_reserve(_SENS.get("vecteurs"))
        reserve = _SENS["reserve"]
    if deja + combien > len(reserve):
        capacite = max(1024, deja + combien + 8192)
        plus_grand = np.zeros((capacite, dim), dtype="float32")
        if deja:
            plus_grand[:deja] = reserve[:deja]
        reserve = plus_grand
        _SENS["reserve"] = reserve
    return reserve, deja


def _sens_refaire_par_message():
    """Pour chaque message (ou ligne d'outil) : la liste de ses passages dans l'index."""
    par = {}
    for i, x in enumerate(_SENS["morceaux"]):
        par.setdefault((x.get("s"), int(x["n"])), []).append(i)
    _SENS["par_message"] = par


def _sens_reecrire_tout():
    """Ecrit l'index entier (fichier temporaire puis renommage). Ne touche QUE ~/Luciana_sens."""
    import numpy as np
    os.makedirs(DOSSIER_SENS, exist_ok=True)
    with _verrou_sens:
        morceaux = list(_SENS["morceaux"])
        vect = _SENS["vecteurs"]
        etat = {"modele": SENS_MODELE, "dim": _SENS["dim"], "conv": _SENS["conv"],
                "outils": _SENS["outils"], "empreinte": _SENS["empreinte"], "version": 1}
    tmp = FICHIER_SENS_MORCEAUX + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        for x in morceaux:
            f.write(json.dumps(x, ensure_ascii=False) + "\n")
    os.replace(tmp, FICHIER_SENS_MORCEAUX)
    tmp = FICHIER_SENS_VECTEURS + ".tmp"
    (vect if vect is not None else np.zeros((0, _SENS["dim"]), dtype="float32")).astype("float16").tofile(tmp)
    os.replace(tmp, FICHIER_SENS_VECTEURS)
    tmp = FICHIER_SENS_ETAT + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(etat, f, ensure_ascii=False)
    os.replace(tmp, FICHIER_SENS_ETAT)


def _sens_ajouter(nouveaux, conv=None, outils=None, empreinte=None):
    """Ajoute des passages a l'index (memoire vive + disque, en ajout seulement)."""
    import numpy as np
    if nouveaux:
        vect = _sens_vecteurs([x["t"] for x in nouveaux])
    os.makedirs(DOSSIER_SENS, exist_ok=True)
    with _verrou_sens:
        if nouveaux:
            depart = len(_SENS["morceaux"])
            _SENS["morceaux"].extend(nouveaux)
            par = _SENS.setdefault("par_message", {})
            for i, x in enumerate(nouveaux):
                par.setdefault((x.get("s"), int(x["n"])), []).append(depart + i)
            # v164 : plus de np.vstack (qui recopiait TOUT l'index a chaque paquet). On ecrit
            # dans la place deja reservee ; le resultat est rigoureusement le meme tableau.
            reserve, deja = _sens_place_pour(len(vect))
            reserve[deja:deja + len(vect)] = vect
            _SENS["vecteurs"] = reserve[:deja + len(vect)]
            with open(FICHIER_SENS_MORCEAUX, "a", encoding="utf-8") as f:
                for x in nouveaux:
                    f.write(json.dumps(x, ensure_ascii=False) + "\n")
            with open(FICHIER_SENS_VECTEURS, "ab") as f:
                vect.astype("float16").tofile(f)
        if conv is not None:
            _SENS["conv"] = conv
        if outils is not None:
            _SENS["outils"] = outils
        if empreinte is not None:
            _SENS["empreinte"] = empreinte
        etat = {"modele": SENS_MODELE, "dim": _SENS["dim"], "conv": _SENS["conv"],
                "outils": _SENS["outils"], "empreinte": _SENS["empreinte"], "version": 1}
    tmp = FICHIER_SENS_ETAT + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(etat, f, ensure_ascii=False)
    os.replace(tmp, FICHIER_SENS_ETAT)


def _sens_vider_index():
    with _verrou_sens:
        _SENS.update(morceaux=[], vecteurs=None, conv=0, outils=0, empreinte="", par_message={},
                     reserve=None)
    _sens_reecrire_tout()


_SENS_EMPREINTE_FICHIERS = {"memoire": None, "outils": None}   # v164 : (taille, date) vues la fois d'avant
_SENS_RESTE = {"messages": 0, "outils": 0}                     # v164 : ce qui attend encore son tour


def _signature_fichier(chemin):
    """(taille, date de derniere ecriture) d'un fichier, ou None. Sert a NE PAS RELIRE un gros
    fichier qui n'a pas bouge : c'est la moitie du travail inutile du fil de fond. Ne leve jamais."""
    try:
        st = os.stat(chemin)
        return (int(st.st_size), int(st.st_mtime))
    except Exception:
        return None


def sens_indexer(hist=None, paquet=256, budget_s=None):
    """Met le grand tiroir a jour : les messages et les resultats d'outils pas encore indexes.
    LIT luciana_memoire.json et archive_outils.jsonl, n'y ECRIT JAMAIS. Si la memoire a ete
    remplacee (fichier abime puis repris sur la veille, par ex.), l'index repart de zero.
    Rend le nombre de passages ajoutes. Ne leve jamais.

    v164 — TROIS CHANGEMENTS, ET AUCUN NE RETIRE QUOI QUE CE SOIT :
      * ON NE PREND PLUS _verrou_tour. On prenait le verrou de la CONVERSATION juste pour lire la
        memoire ; comme repondre() le garde pendant tout un tour, le fil de fond attendait la fin
        du tour et la duree mesuree melangeait l'attente et le travail. La memoire est ecrite par
        remplacement d'un coup (os.replace) : la lire sans verrou donne toujours un fichier entier.
      * BUDGET DE TEMPS (budget_s) : on s'arrete proprement A UNE FRONTIERE DE PAQUET quand le
        temps est ecoule. RIEN N'EST PERDU : le marque-page (_SENS["conv"] / _SENS["outils"]) dit
        ou on s'est arrete, la tranche suivante reprend exactement la.
      * ON NE RELIT PAS un fichier qui n'a pas bouge depuis la derniere fois (taille + date)."""
    if _SENS["moteur"] is None:
        return 0
    ajoutes = 0
    date_limite = None if not budget_s else (time.monotonic() + float(budget_s))

    def _temps_fini():
        return date_limite is not None and time.monotonic() >= date_limite

    try:
        sig_mem = _signature_fichier(FICHIER_MEMOIRE)
        if hist is None:
            # v164 : rien n'a bouge ET rien n'attend -> on ne relit meme pas le gros fichier JSON.
            if (sig_mem is not None and sig_mem == _SENS_EMPREINTE_FICHIERS["memoire"]
                    and not _SENS_RESTE["messages"]):
                hist = None
            else:
                hist = charger_memoire()
        if hist is not None:
            with _verrou_sens:
                deja, empreinte = _SENS["conv"], _SENS["empreinte"]
            if deja > len(hist) or (deja and _empreinte_message(hist[deja - 1]) != empreinte):
                _controle_sens({"quoi": "index repart de zero", "raison": "la memoire a change sous lui",
                                "deja": deja, "messages": len(hist)})
                _sens_vider_index()
                deja = 0
            i = deja
            while i < len(hist):
                fin = min(len(hist), i + paquet)
                nouveaux = []
                for n in range(i, fin):
                    m = hist[n]
                    c = m.get("content")
                    if not isinstance(c, str):
                        c = str(c)
                    for k, t in enumerate(_decouper(c)):
                        nouveaux.append({"s": "conv", "n": n, "k": k, "d": str(m.get("date") or ""),
                                         "r": "Fred" if m.get("role") == "user" else NOM_ASSISTANTE,
                                         "t": t})
                _sens_ajouter(nouveaux, conv=fin, empreinte=_empreinte_message(hist[fin - 1]))
                ajoutes += len(nouveaux)
                i = fin
                if _temps_fini():
                    break
            _SENS_RESTE["messages"] = max(0, len(hist) - i)
            if not _SENS_RESTE["messages"]:
                _SENS_EMPREINTE_FICHIERS["memoire"] = sig_mem
        # L'archive des outils (mails lus, pages, resultats...) : meme principe, ligne par ligne.
        sig_out = _signature_fichier(FICHIER_ARCHIVE_OUTILS)
        relire = (sig_out is None or sig_out != _SENS_EMPREINTE_FICHIERS["outils"]
                  or _SENS_RESTE["outils"])
        if relire and not _temps_fini():
            try:
                with open(FICHIER_ARCHIVE_OUTILS, "r", encoding="utf-8") as f:
                    lignes = f.readlines()
            except Exception:
                lignes = []
            j = _SENS["outils"]
            while j < len(lignes):
                fin = min(len(lignes), j + paquet)
                nouveaux = []
                for n in range(j, fin):
                    try:
                        a = json.loads(lignes[n])
                    except Exception:
                        continue
                    texte = "%s %s" % (a.get("entree", ""), a.get("resultat", ""))
                    for k, t in enumerate(_decouper(texte)):
                        nouveaux.append({"s": "outil", "n": n, "k": k, "d": str(a.get("date") or ""),
                                         "r": str(a.get("outil") or "?"), "t": t})
                _sens_ajouter(nouveaux, outils=fin)
                ajoutes += len(nouveaux)
                j = fin
                if _temps_fini():
                    break
            _SENS_RESTE["outils"] = max(0, len(lignes) - j)
            if not _SENS_RESTE["outils"]:
                _SENS_EMPREINTE_FICHIERS["outils"] = sig_out
    except Exception as ex:
        _SENS["erreur"] = "indexation : %s" % str(ex)[:200]
        _controle_sens({"quoi": "indexation en panne", "erreur": _SENS["erreur"]})
    return ajoutes


def sens_installer_moteur(moteur):
    """Branche un moteur (le vrai, ou un faux pour les tests) et relit l'index du disque.

    v164 : ON RELIT AUSSI LE PETIT CACHE D'EMPREINTES depuis le disque. AVANT, on le vidait, et le
    PREMIER message apres un redemarrage devait donc recalculer ~30 000 empreintes de fiches dans
    le tour de Fred -- c'est la cause mesuree des attentes de 10 a 30 minutes « depuis le
    redemarrage ». Si le cache du disque manque ou ne correspond pas, on repart de rien : c'est un
    cache, il se refait tout seul (et le fil de fond le pre-chauffe pendant les temps morts)."""
    _SENS_DERNIERES_PHRASES.clear()
    _SENS_PETIT_CACHE.clear()
    vect = moteur.vecteurs(["dimension"])
    _SENS["moteur"] = moteur
    _SENS["dim"] = int(vect.shape[1])
    if not _sens_charger_index():
        _sens_vider_index()
    relus = _petit_cache_charger()
    _SENS_CACHE_ECRIT.update(combien=relus, quand=time.monotonic())
    if relus:
        _controle_sens({"quoi": "petit cache de sens relu du disque", "empreintes": relus})
    _SENS["etat"] = "pret"
    _SENS["erreur"] = ""


def _boucle_memoire_sens():
    """Au demarrage : charge le moteur (la premiere fois : installation + telechargement du
    modele), puis remplit le grand tiroir avec toute la memoire, puis le tient a jour. Tourne en
    fond : Luciana repond normalement pendant ce temps. Ne leve jamais.

    v164 — LA BOUCLE NE PASSE PLUS JAMAIS DEVANT FRED :
      * elle regarde toutes les 5 s (au lieu de 30) s'il y a du CALME ;
      * elle ne demarre une tranche que si aucun tour n'est en cours et que le dernier est fini
        depuis au moins SENS_CALME_SECONDES ;
      * une tranche dure au plus SENS_TRANCHE_SECONDES (~20 s). Ce qui reste repart a la tranche
        suivante : RIEN N'EST ABANDONNE, tout est seulement DECALE ;
      * la mesure ecrite dans le carnet separe maintenant honnetement l'ATTENTE et le TRAVAIL, et
        dit ce qu'il RESTE a faire -- c'est ce qui manquait pour lire les chiffres du 12/10 ;
      * pendant les temps morts, elle PRE-CHAUFFE les empreintes des fiches de la bibliotheque,
        par petites tranches, pour que le premier message apres un redemarrage ne paie plus rien.
    """
    if not REGLAGE_SENS.get("actif"):
        _SENS["etat"] = "eteint (reglage_memoire_sens.json)"
        return
    essais = 0
    while _SENS["moteur"] is None:
        try:
            _SENS["etat"] = "chargement du moteur"
            sens_installer_moteur(_MoteurFastembed())
            _controle_sens({"quoi": "moteur pret", "modele": SENS_MODELE, "dim": _SENS["dim"]})
        except Exception as ex:
            essais += 1
            _SENS["etat"] = "en panne"
            _SENS["erreur"] = str(ex)[:300]
            _controle_sens({"quoi": "moteur en panne (choix par les mots en attendant)",
                            "erreur": _SENS["erreur"], "essai": essais})
            time.sleep(min(3600, 60 * essais))
    attendu = 0.0
    while True:
        try:
            if not _le_calme_est_revenu():
                # un tour est en cours (ou vient de finir) : on ne touche a rien, on recompte
                # l'attente pour pouvoir la DIRE dans le carnet au lieu de la melanger au travail.
                attendu += SENS_BOUCLE_SOMMEIL
                time.sleep(SENS_BOUCLE_SOMMEIL)
                continue
            debut = time.monotonic()
            # paquet plus petit qu'avant (64 au lieu de 256) : le budget de temps est verifie A
            # CHAQUE paquet, donc plus les paquets sont petits, plus on colle aux 20 s promises.
            n = sens_indexer(paquet=64, budget_s=SENS_TRANCHE_SECONDES)
            travail = time.monotonic() - debut
            if n:
                reste = int(_SENS_RESTE["messages"]) + int(_SENS_RESTE["outils"])
                _controle_sens({"quoi": "grand tiroir mis a jour", "passages_ajoutes": n,
                                "passages_en_tout": len(_SENS["morceaux"]),
                                # 'secondes' garde son sens d'avant (le carnet reste lisible),
                                # mais on dit maintenant ce qu'il y a DEDANS.
                                "secondes": round(travail, 1),
                                "travail_s": round(travail, 1),
                                "attente_s": round(attendu, 1),
                                "par_passage_s": round(travail / max(1, n), 3),
                                "reste_a_faire": reste,
                                "tranche_s": SENS_TRANCHE_SECONDES,
                                "v164": True})
            attendu = 0.0
            # Temps mort : on avance le pre-chauffage des empreintes de fiches, par tranches.
            if not n and _le_calme_est_revenu():
                _sens_prechauffer_les_fiches()
            # L'ecriture du cache sur le disque ne se fait QUE dans le calme : jamais pendant que
            # la conversation se sert du cache.
            if _le_calme_est_revenu():
                _petit_cache_sauver()
        except Exception:
            pass
        time.sleep(SENS_BOUCLE_SOMMEIL)


_PRECHAUFFE = {"empreinte_arbre": None, "faits": 0, "restants": 0, "fini": False}


def _sens_prechauffer_les_fiches():
    """v164 — LE PRE-CHAUFFAGE. Calcule D'AVANCE, pendant les temps morts, les empreintes de sens
    des fiches de la bibliotheque, par tranches de SENS_PRECHAUFFE_PAR_TRANCHE. Lecture SEULE de
    l'arbre : la bibliotheque n'est ni modifiee ni reorganisee, on ne fait que preparer le calcul
    que le tour de Fred faisait jusqu'ici dans son dos. S'arrete des qu'un tour redemarre.
    Ne leve jamais : un pre-chauffage rate ne doit casser aucune reponse."""
    try:
        import hashlib
        if _v196_moteur_google_choisi():
            return _v196_prechauffer_google()
        if not sens_pret() or not biblio2_branche():
            return 0
        sig = _signature_fichier(_BIBLIO2_ARBRE)
        if sig is None:
            return 0
        if sig != _PRECHAUFFE["empreinte_arbre"]:
            _PRECHAUFFE.update(empreinte_arbre=sig, faits=0, restants=0, fini=False)
        if _PRECHAUFFE["fini"]:
            return 0
        arbre = _biblio2_arbre()
        if not arbre:
            return 0
        a_faire, vus, tout_vu = [], set(), True
        for cat, sous, fi in _biblio2_toutes_les_fiches(arbre):
            if len(a_faire) >= SENS_PRECHAUFFE_PAR_TRANCHE or not _le_calme_est_revenu():
                tout_vu = False      # tranche pleine, ou Fred revient : on reprendra ici
                break
            tous, _etiq, _morceaux = _biblio2_bouts_de_fiche(cat, sous, fi)
            for b in tous:
                h = hashlib.sha1(b.encode("utf-8", "replace")).hexdigest()
                if h not in _SENS_PETIT_CACHE and h not in vus:
                    vus.add(h)
                    a_faire.append((h, b))
        if not a_faire:
            # on n'a trouve plus rien a faire ET on a bien tout parcouru : c'est fini pour cet arbre
            if tout_vu and not _PRECHAUFFE["fini"]:
                _PRECHAUFFE["fini"] = True
                _controle_sens({"quoi": "pre-chauffage des fiches termine",
                                "empreintes_pretes": len(_SENS_PETIT_CACHE),
                                "calculees_en_tout": _PRECHAUFFE["faits"], "v164": True})
                _petit_cache_sauver(force=True)
            return 0
        debut = time.monotonic()
        vect = _sens_vecteurs([b for _h, b in a_faire])
        _petit_cache_poser_lot(a_faire, vect)
        _PRECHAUFFE["faits"] += len(a_faire)
        _controle_sens({"quoi": "pre-chauffage des fiches (temps mort)",
                        "empreintes_calculees": len(a_faire),
                        "secondes": round(time.monotonic() - debut, 1),
                        "en_cache": len(_SENS_PETIT_CACHE), "v164": True})
        return len(a_faire)
    except Exception:
        return 0


def _v196_prechauffer_google():
    """V196 : le meme pre-chauffage, avec le moteur de Google : pendant les temps morts, les fiches
    nouvellement rangees par l'archiviste recoivent leur empreinte (une seule fois, gardee sur le
    disque). Une tranche a la fois, on s'arrete des que Fred revient. Ne leve jamais."""
    try:
        if not biblio2_branche():
            return 0
        sig = _signature_fichier(_BIBLIO2_ARBRE)
        if sig is None:
            return 0
        if sig != _PRECHAUFFE["empreinte_arbre"]:
            _PRECHAUFFE.update(empreinte_arbre=sig, faits=0, restants=0, fini=False)
        if _PRECHAUFFE["fini"]:
            return 0
        mg = _biblio2_moteur_google()
        arbre = _biblio2_arbre() if mg is not None else None
        if not arbre:
            return 0
        import biblio2_moteur_google as _mgm
        a_faire, vus, tout_vu = [], set(), True
        for cat, sous, fi in _biblio2_toutes_les_fiches(arbre):
            if len(a_faire) >= _mgm.PAR_APPEL or not _le_calme_est_revenu():
                tout_vu = False
                break
            tous, _etiq, _morceaux = _biblio2_bouts_de_fiche(cat, sous, fi)
            for b in tous:
                if b not in vus and not mg.deja_calcule([b]):
                    vus.add(b)
                    a_faire.append(b)
        if not a_faire:
            if tout_vu:
                _PRECHAUFFE["fini"] = True
            return 0
        debut = time.monotonic()
        mg.vecteurs(a_faire, "RETRIEVAL_DOCUMENT")
        _PRECHAUFFE["faits"] += len(a_faire)
        _controle_sens({"quoi": "pre-chauffage des fiches, moteur de Google (temps mort)",
                        "empreintes_calculees": len(a_faire),
                        "secondes": round(time.monotonic() - debut, 1), "v196": True})
        return len(a_faire)
    except Exception:
        return 0


_verrou_biblio = threading.RLock()


FICHIER_COMPTEUR_AVIS = os.path.join(DOSSIER, "compteur_avis_luciana.json")


# ---------------------------------------------------------------------
#  (3) LE COMPTEUR VISIBLE "Avis donnes / tours sans avis"
# ---------------------------------------------------------------------
#  Meme montage que le compteur de la v99 et celui de la v135 : un petit fichier a part, le chiffre
#  survit a un F5 et a un redemarrage, il ne touche a AUCUN fichier de memoire, et un clic sur la
#  ligne le remet a zero (l'ancien chiffre est garde, date, dans le meme fichier).
#  QUI COMPTE : LE PROGRAMME, a la fin de chaque tour ou la bibliotheque a servi des passages.
#  Luciana ne peut ni l'oublier, ni l'arrondir, ni se mettre une bonne note toute seule.
_verrou_compteur_avis = threading.Lock()


def _lire_compteur_avis():
    try:
        with open(FICHIER_COMPTEUR_AVIS, encoding="utf-8-sig") as f:
            d = json.load(f)
        return d if isinstance(d, dict) else {}
    except Exception:
        return {}


def remettre_a_zero_avis():
    """Le clic de Fred sur la ligne : le compteur repart de 0. Les anciens chiffres ne sont pas
    effaces en douce, ils sont gardes dans le meme fichier (remises), dates.
    LE JOURNAL DES AVIS (avis_de_luciana.jsonl) N'EST PAS TOUCHE : remettre le compteur a zero
    n'efface aucun avis, c'est l'archiviste qui en a besoin."""
    with _verrou_compteur_avis:
        d = _lire_compteur_avis()
        avant = {"avis_donnes": int(d.get("avis_donnes") or 0),
                 "tours_sans_avis": int(d.get("tours_sans_avis") or 0),
                 "tours_concernes": int(d.get("tours_concernes") or 0)}
        historique = d.get("remises") if isinstance(d.get("remises"), list) else []
        historique.append(dict(avant, quand=time.strftime("%d/%m/%Y a %Hh%M")))
        neuf = {"avis_donnes": 0, "tours_sans_avis": 0, "tours_avec_avis": 0,
                "tours_concernes": 0, "refuses": 0,
                # v144 : la serie repart de zero elle aussi. Sans tour sans avis, le voyant est
                # eteint de toute facon : c'est coherent, et ca ne cache rien.
                "tours_avec_avis_de_suite": 0,
                "depuis": time.strftime("%d/%m/%Y a %Hh%M"),
                "remises": historique[-50:]}
        try:
            tmp = FICHIER_COMPTEUR_AVIS + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(neuf, f, ensure_ascii=False, indent=1)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp, FICHIER_COMPTEUR_AVIS)
        except Exception:
            pass
        return avant


def demarrer_memoire_sens():
    threading.Thread(target=_boucle_memoire_sens, name="memoire-sens", daemon=True).start()


# =====================================================================
#  v146 (demande de Fred, 09/10/2026) : LE VERROU DE SURVEILLANCE -- "LA NOUNOU"
#
#  SES MOTS, EXACTEMENT : "tu ne peux pas les modifier sans que j'aie clique sur quelque
#  chose ; tu me proposes, je valide, je clique, sinon on modifie pas."
#
#  POURQUOI : Luciana ecrit toute seule dans ses propres fichiers (ses consignes, son carnet de
#  chantier, ses souvenirs, ses choses en cours, ses fiches). Le soir du 08/10/2026, une de ces
#  ecritures faites SANS demander a casse quelque chose, et deux fichiers d'etat se sont
#  retrouves vides. Fred veut voir CHAQUE ecriture avant qu'elle parte.
#
#  COMMENT CA MARCHE, EN TROIS PHRASES :
#   1) Quand Luciana veut ecrire dans un de SES fichiers de contenu, l'ecriture ne part pas :
#      elle est DEPOSEE dans une file d'attente (~\Luciana\a_valider.jsonl) avec la date,
#      le fichier vise, l'outil qui demande, une phrase d'explication courte, et le contenu
#      propose -- avec l'ancien et le nouveau cote a cote quand c'est possible.
#   2) Le panneau "A VALIDER" de la page montre la liste. Deux boutons par ligne : VALIDER
#      (l'ecriture se fait POUR DE VRAI, maintenant) et REFUSER (la ligne part, RIEN n'est
#      ecrit). Un compteur dit combien de choses attendent.
#   3) L'INTERRUPTEUR est tout en haut du panneau "Cles", impossible a manquer. Trois
#      positions : SURVEILLE (le defaut : rien ne s'ecrit sans clic), EN VEILLE et ETEINT
#      (tout s'ecrit comme en v145, aucun blocage, aucune ligne dans la file). Fred seul
#      le change, et le changement prend effet TOUT DE SUITE (le reglage est relu sur le
#      disque a chaque ecriture : rien a relancer).
#
#  CE QUI N'EST JAMAIS BLOQUE, PARCE QUE CA CASSERAIT LE PROGRAMME (regle d'or n22) :
#   - toutes les LECTURES, sans exception : la nounou ne regarde que les ecritures ;
#   - les JOURNAUX qui s'ecrivent tout seuls (journal des conversations, des outils, des
#     alertes, de la veille, des gestes du tiroir, de la bibliotheque, du rangement) ;
#   - les SAUVEGARDES automatiques de la memoire et des fichiers ;
#   - les COMPTEURS DE COUTS (couts_appels.jsonl, depenses.json) ;
#   - tout FICHIER TECHNIQUE du programme : cles, jetons, reglages, compteurs, etats de
#     chantier, memoire de la conversation ;
#   - et tout ce qu'ecrivent les BOUCLES DE FOND (le rangement de la journee, la veille,
#     l'archiviste, le veilleur des travaux). La nounou ne mord QUE pendant un appel d'outil
#     de Luciana : c'est la definition exacte de "le CONTENU que Luciana DECIDE d'ecrire".
#
#  ROBUSTESSE (point 5 de Fred) :
#   - la file est un journal qui ne fait que S'AJOUTER (comme consignes.jsonl) : une decision
#     est une ligne de PLUS, jamais une reecriture. Rien ne peut y disparaitre ;
#   - une ligne illisible est SAUTEE, jamais corrigee et jamais effacee ;
#   - si la file elle-meme ne peut pas etre ecrite, l'ecriture est REFUSEE et on le DIT
#     franchement : jamais une ecriture "quand meme", jamais une demande perdue en silence ;
#   - page fermee, programme arrete, PC redemarre : la demande est sur le disque, elle attend.
#     Le clic de Fred est la seule chose qui la fait partir ;
#   - si la validation rate, la demande RESTE dans la file (on ne la referme pas) ;
#   - la nounou ne fait jamais tomber le programme : la seule chose qu'elle leve est
#     DemandeEnAttenteDeFred, attrapee a UN SEUL endroit (_executer_outil), qui rend a Luciana
#     une phrase claire -- "c'est depose, ca attend son clic" -- et le tour continue.
#
#  CHEZ LUCIANA, PAS CHEZ LUMINITA (point 6 de Fred) : tout ce bloc est eteint quand le
#  programme tourne sous le nom Luminita. Son comportement ne change pas d'un caractere.
#
#  CONTROLE : _verif_v146_nounou.py (il relit chaque point ci-dessus dans ce fichier et dit
#  clairement ce qui rate).
# =====================================================================
NOUNOU_MODE_SURVEILLE = "surveille"   # le defaut : rien ne s'ecrit sans clic
NOUNOU_MODE_VEILLE = "veille"         # tout s'ecrit comme en v145
NOUNOU_MODE_ETEINT = "eteint"         # idem : aucun blocage
NOUNOU_MODE_DEFAUT = NOUNOU_MODE_SURVEILLE

# LE REGLAGE EST DANS LE DOSSIER PRIVE DE FRED (~\Luciana), et pas a cote du programme : c'est
# LUI qui le change d'un clic, et son choix doit survivre a une mise a jour de Luciana.
FICHIER_REGLAGE_NOUNOU = os.path.join(DOSSIER, "reglage_nounou.json")
# LA FILE D'ATTENTE. Le nom demande par Fred. Journal : AJOUT SEUL, jamais de reecriture.
FICHIER_A_VALIDER = os.path.join(DOSSIER, "a_valider.jsonl")
# LE JOURNAL DES DECISIONS (deposee / valide / refuse / rate). Il ne sert pas a calculer la
