def _ajouter_ligne_jsonl(chemin, enregistrement):
    """AJOUTE une ligne a la fin du fichier. Le fichier n'est JAMAIS relu-puis-reecrit : rien ne
    peut disparaitre par accident, meme si le PC s'eteint au mauvais moment.

    v146 : LA NOUNOU PASSE D'ABORD. Si Fred surveille les ecritures et que ce fichier est un de
    SES fichiers de contenu, la ligne est deposee dans sa file et RIEN n'est ecrit ici. En
    veille ou eteint, le 'if' ci-dessous est FAUX tout de suite : on ne calcule rien, on ne
    relit rien, et cette fonction se comporte EXACTEMENT comme en v145."""
    if nounou_doit_demander(chemin):
        nounou_controler(chemin, "ajout_jsonl",
                         {"chemin": chemin, "enregistrement": enregistrement},
                         explication=_nounou_phrase_ajout(chemin, enregistrement),
                         nouveau=json.dumps(enregistrement, ensure_ascii=False, indent=1))
    with _verrou_consignes:
        with open(chemin, "a", encoding="utf-8") as f:
            f.write(json.dumps(enregistrement, ensure_ascii=False) + "\n")
            f.flush()
            os.fsync(f.fileno())
    return enregistrement


def _lire_lignes_jsonl(chemin):
    """Toutes les lignes du fichier, dans l'ordre ou elles ont ete ecrites. Une ligne abimee est
    sautee : elle ne fait jamais perdre les autres."""
    lignes = []
    try:
        with open(chemin, "r", encoding="utf-8", errors="replace") as f:
            for brut in f:
                brut = brut.strip()
                if not brut:
                    continue
                try:
                    d = json.loads(brut)
                except Exception:
                    continue
                if isinstance(d, dict):
                    lignes.append(d)
    except FileNotFoundError:
        pass
    except Exception:
        pass
    return lignes


def _prochain_numero(chemin):
    """Le prochain numero libre. Un numero n'est JAMAIS reutilise, meme apres un retrait : comme
    ca, quand Fred dit 'retire la consigne 7', il n'y a aucune confusion possible."""
    n = 0
    for d in _lire_lignes_jsonl(chemin):
        try:
            n = max(n, int(d.get("numero") or 0))
        except Exception:
            pass
    return n + 1


def _jj_mm(horodatage):
    j = _jour_de(horodatage)
    return "%s/%s" % (j[8:10], j[5:7]) if j else "?"


def _date_dans(jours):
    """La date dans 'jours' jours, au format AAAA-MM-JJ."""
    return time.strftime("%Y-%m-%d", time.localtime(time.time() + int(jours) * 86400))


def _duree_en_jours(x):
    """'3 jours', 'une semaine', 'un mois', 'pour toujours', 'aujourd'hui'... -> un nombre de
    jours. -1 = sans limite de temps. None = je n'ai pas compris (on prendra le defaut)."""
    t = _sans_accents(str(x or "")).strip()
    if not t:
        return None
    if any(m in t for m in ("toujours", "definitif", "sans limite", "indefini", "plus jamais")):
        return -1
    if "aujourd" in t or "ce soir" in t or "la journee" in t or "heure" in t:
        return 0
    if "demain" in t:
        return 1
    m = re.search(r"(\d+)", t)
    n = int(m.group(1)) if m else 1
    if not m:   # "deux semaines", "trois jours"... : Fred parle, il ne tape pas des chiffres
        for mot, combien in (("deux", 2), ("trois", 3), ("quatre", 4), ("cinq", 5), ("six", 6),
                             ("sept", 7), ("huit", 8), ("neuf", 9), ("dix", 10), ("quinze", 15)):
            if mot in t:
                n = combien
                break
    if "semaine" in t:
        return n * 7
    if "mois" in t:
        return n * 30
    if "an" in t:
        return n * 365
    if "jour" in t:
        return n
    return n if m else None


def _date_en_clair(jusqu_au):
    j = str(jusqu_au or "")
    if not j or j >= DATE_SANS_LIMITE:
        return "sans limite de temps"
    return "jusqu'au %s" % _jj_mm(j)


# ---------- le carnet de consignes ----------
def consignes_actives():
    """Rejoue le fichier ligne par ligne (ajout, correction, retrait) et rend les consignes encore
    valables, de la plus ancienne a la plus recente. Rien n'est efface du fichier : on se contente
    de tenir compte de ce qui a ete ecrit apres."""
    vivantes = {}
    for d in _lire_lignes_jsonl(FICHIER_CONSIGNES):
        try:
            num = int(d.get("numero") or 0)
        except Exception:
            num = 0
        if not num:
            continue
        action = _sans_accents(str(d.get("action") or "ajouter")).strip()
        if action.startswith("oubli") or action.startswith("retir") or action.startswith("suppr"):
            vivantes.pop(num, None)
            continue
        texte = str(d.get("texte") or "").strip()
        if not texte:
            continue
        ancienne = vivantes.get(num) or {}
        vivantes[num] = {
            "numero": num,
            "texte": texte,
            "importance": str(d.get("importance") or ancienne.get("importance") or "normale"),
            "date": ancienne.get("date") or str(d.get("date") or ""),
            "corrigee": str(d.get("date") or "") if action.startswith("corrig") else ancienne.get("corrigee", ""),
        }
    return [vivantes[n] for n in sorted(vivantes)]


def _est_capitale(c):
    return _sans_accents(str(c.get("importance") or "")).startswith("capital")


# v97 : la derniere mesure des souvenirs et des carnets envoyes (remplie par repondre(), lue par
# mesure_memoire() pour l'afficher a Fred dans le bandeau d'etat des travaux).
_MESURE_MEMOIRE = {"souvenirs": 0, "carnets": 0, "quand": 0.0}


def _entete_consigne(c):
    return "- n%d (note le %s%s)%s : " % (
        c["numero"], _jj_mm(c.get("date")),
        ", corrigee le %s" % _jj_mm(c["corrigee"]) if c.get("corrigee") else "",
        " IMPORTANT" if _est_capitale(c) else "")


def _ligne_entiere(c):
    """La consigne EN ENTIER, mot pour mot, avec son entete. Rien n'est resume ni abime."""
    return _entete_consigne(c) + re.sub(r"[ \t]+", " ", str(c.get("texte") or "")).strip()


# LE NOYAU DE LA v140 : les 4 regles protegees retenues par Fred ce soir. C'est la liste par
# DEFAUT ; Fred garde la main par noyau_consignes.json (le meme fichier qu'avant, il n'y a pas
# deux endroits a tenir a jour).
NOYAU_CONSIGNES_V140 = [6, 9, 22, 8]

CONSIGNES_V140_SUJET_MAX = 180         # longueur de la phrase de description d'une consigne
CONSIGNES_V140_SUJET_MIN = 60          # ... et quand la place manque dans l'index (mais la ligne


def noyau_consignes_v140():
    """LES NUMEROS DU NOYAU DE LA v140. Fred garde la main : s'il ecrit une liste dans
    noyau_consignes.json, c'est la sienne qui vaut (meme fichier qu'avant, un seul endroit a
    tenir). Fichier absent -> les 4 regles retenues ce soir. Ne leve jamais, n'ecrit rien."""
    try:
        with open(FICHIER_NOYAU_CONSIGNES, "r", encoding="utf-8") as f:
            d = json.load(f)
        brut = d.get("noyau") if isinstance(d, dict) else d
        if isinstance(brut, list):
            nums = []
            for x in brut:
                try:
                    n = int(x)
                except Exception:
                    continue
                if n > 0 and n not in nums:
                    nums.append(n)
            return nums              # une liste vide est un choix valable : Fred veut l'index seul
    except Exception:
        pass
    return list(NOYAU_CONSIGNES_V140)


# ---------------------------------------------------------------------
#  (1) LE SUJET D'UNE CONSIGNE : SES PROPRES MOTS, JAMAIS UNE ETIQUETTE VENUE D'AILLEURS
# ---------------------------------------------------------------------
def sujet_de_la_consigne(c):
    """LA PHRASE DE DESCRIPTION D'UNE CONSIGNE : sa PREMIERE PHRASE, mise sur une ligne.

    POURQUOI COMME CA, ET PAS AUTREMENT. C'est ce qui corrige le defaut mesure ce soir : la v107
    collait a chaque regle le nom d'un RAYON DE LA BIBLIOTHEQUE, d'ou "n30 [trading]" pour une
    regle qui parle du suivi de la communication. Ici le sujet est fait des mots de la consigne
    ELLE-MEME : il ne peut donc pas etre faux, et il ne depend d'aucun autre fichier.
    ON NE DEVINE RIEN, ON N'INVENTE RIEN, ON N'ECRIT RIEN : consignes.jsonl n'est ni relu
    autrement ni modifie. Ne leve jamais."""
    t = re.sub(r"\s+", " ", str((c or {}).get("texte") or "")).strip()
    if not t:
        return ""
    # La premiere phrase, quand elle existe et qu'elle n'est pas ridicule de courte.
    coupe = t[:CONSIGNES_V140_SUJET_MAX]
    for separateur in (". ", " ; ", " : ", " - "):
        place = coupe.find(separateur)
        if place >= 25:
            return coupe[:place].strip()
    if len(t) <= CONSIGNES_V140_SUJET_MAX:
        return t
    # Pas de fin de phrase : on coupe sur un blanc, jamais au milieu d'un mot.
    blanc = coupe.rfind(" ")
    return (coupe[:blanc] if blanc >= CONSIGNES_V140_SUJET_MAX // 2 else coupe).strip()


def sujets_des_consignes(actives):
    """{numero: phrase de description}. Ne leve jamais : une consigne dont le sujet se calcule mal
    garde un sujet vide, et sa ligne d'index existe quand meme."""
    sujets = {}
    for c in (actives or []):
        try:
            sujets[c["numero"]] = sujet_de_la_consigne(c)
        except Exception:
            sujets[c["numero"]] = ""
    return sujets


def _ligne_index_v140(c, sujet, en_entier, taille=CONSIGNES_V140_SUJET_MAX):
    """UNE ligne d'index pour UNE consigne. C'est la ligne qui garantit qu'aucune regle ne disparait
    jamais : son numero y est TOUJOURS, et son sujet avec -- son VRAI sujet, fait de ses mots.
    'taille' = la longueur du sujet affiche. Quand la place manque, c'est le SUJET qui raccourcit,
    JAMAIS la ligne qui s'efface : le numero est toujours la, et il reste ouvrable."""
    # DEJA DONNEE EN ENTIER PLUS HAUT : on ne recopie PAS son sujet ici, et ce n'est pas un detail
    # de presentation. C'est ce qui rend la reserve de place du point 1 mathematiquement sure :
    # une ligne "donnee en entier" est TOUJOURS plus courte qu'une ligne de sujet au format le plus
    # court. Donc l'index ne peut JAMAIS depasser la reserve calculee pour lui, et aucune ligne ne
    # peut etre sacrifiee faute de place.
    if c["numero"] in en_entier:
        return "- n%d : (donnee EN ENTIER plus haut)" % c["numero"]
    suj = str(sujet or "").strip() or "(sans phrase de description)"
    if len(suj) > max(20, int(taille)):
        suj = suj[:max(20, int(taille))].rstrip(" .,;:") + " [...]"
    return "- n%d : %s" % (c["numero"], suj)


def _poids_index_v140(actives, sujets, en_entier, taille=CONSIGNES_V140_SUJET_MAX):
    return sum(len(_ligne_index_v140(c, sujets.get(c["numero"]) or "", en_entier, taille)) + 1
               for c in actives)


def _en_car(n):
    """13444 -> "13 444" : un nombre lisible par Fred, sans virgule anglaise."""
    try:
        return "{:,}".format(int(n)).replace(",", " ")
    except Exception:
        return str(n)


# =====================================================================
#  v110 (demande de Fred, 05/10/2026 a 18h33) : LES VOYANTS.
#  SES MOTS : "que ca reste toujours allume en jaune parce que c'est marque A TRIER et ca il faut
#  le modifier... tout ce qui va s'allumer en jaune comme ca avec des petits panneaux ATTENTION,
#  ca c'est un appel du client qui va me deranger qui va nous deranger."
#
#  LE DEFAUT, CONSTATE DANS LE CODE (et pas raconte) : la ligne qui allumait le voyant jaune du
#  bandeau de memoire etait, en v109 :
#      a_trier = bool(refusees) or consignes > CONSIGNES_CARACTERES_MAX
#                or total > MEMOIRE_CARACTERES_MAX
#  Le coupable, c'est le TROISIEME morceau. Le total (consignes + souvenirs + carnets) depasse le
#  plafond EN PERMANENCE, et c'est un etat NORMAL, pas un defaut : ce plafond n'efface rien, il
#  choisit seulement ce qui part dans le message, et tout le reste reste entier sur le disque.
#  Resultat : le voyant etait allume tout le temps. Un voyant toujours allume n'informe plus
#  personne -- il inquiete. Et chez un client, il fait decrocher le telephone.
#
#  CE QUI CHANGE, ET C'EST TOUT : le voyant ne s'allume plus QUE pour un vrai probleme, un
#  probleme qui demande une ACTION :
#    (a) refusees : une consigne CAPITALE que le programme n'a PAS pu servir. La, une regle de
#        Fred est tombee pour de vrai, et il FAUT le dire.
#    (b) le plafond DUR des consignes (CONSIGNES_CARACTERES_MAX = 30 000 depuis la v132 ; ce
#        commentaire annoncait encore 9 000, corrige le 07/10/2026 en v135) est depasse.
#  TOUT LE RESTE : SILENCE.
#
#  MISE A JOUR DU 13/10/2026 (ordre de Fred) : LE TROISIEME MORCEAU EST RETIRE DES DEUX COTES.
#  La v110 l'avait deja neutralise quand l'interrupteur des voyants est allume, mais la branche
#  de secours (interrupteur eteint) le gardait. Il n'y est plus non plus : IL N'Y A PAS DE
#  PLAFOND DE MEMOIRE, donc un total ne peut pas etre « trop grand », et il n'a plus a inquieter
#  Fred dans AUCUN des deux cas. Le nombre, lui, existe toujours et travaille toujours, mais il
#  s'appelle maintenant BUDGET_ENTETE_CARACTERES, parce que c'est ce qu'il est : la place du
#  detail des carnets dans UN message.
#
#  CE QUI NE CHANGE PAS : ce nombre garde EXACTEMENT sa valeur (150 000) et EXACTEMENT son
#  travail de garde-fou interne (c'est lui qui retrecit le detail des carnets dans repondre()).
#  Il n'allume simplement PLUS RIEN a l'ecran. Aucun mur, aucun blocage, aucun refus de
#  travailler : ce voyant n'a jamais rien coupe, et il ne coupe toujours rien. C'est une
#  etiquette, pas un verrou.
#
#  LA REGLE D'OR POUR LE CLIENT (demande de Fred) : un panneau ne doit JAMAIS demander au client
#  quelque chose qu'il ne peut pas faire. Si le programme peut se debrouiller seul, il le fait EN
#  SILENCE et n'affiche rien. Il ne parle QUE s'il ne peut vraiment pas -- et alors il dit QUOI
#  FAIRE, en une phrase simple, sans jargon. C'est pour ca que le texte du voyant donne
#  maintenant la marche a suivre au lieu d'un simple "A TRIER" sec.
#
#  L'INTERRUPTEUR (regle d'or n22 : ne rien casser) : le fichier reglage_voyants.json, a cote du
#  programme, exactement comme reglage_allegement.json. Mets "voyants_v110_actif": false, relance
#  Luciana, et on retrouve EXACTEMENT la v109 : l'ancienne condition et l'ancien texte, a la
#  virgule pres. Rien n'a ete efface.
# =====================================================================
FICHIER_REGLAGE_VOYANTS = os.path.join(DOSSIER_PROG, "reglage_voyants.json")

_EXPLICATION_REGLAGE_VOYANTS = (
    "true = la v110 : le voyant jaune du bandeau de memoire ne s'allume QUE pour un vrai "
    "probleme qui demande une action, c'est-a-dire une consigne capitale que le programme n'a "
    "pas pu servir, ou le plafond DUR des consignes (9000 caracteres depuis la v121) depasse. "
    "Le plafond global de memoire reste un garde-fou interne, mais il n'allume plus rien : le "
    "depasser est un etat NORMAL, pas un defaut. "
    "false = on retrouve exactement la v109 : le voyant se rallume aussi des que le total "
    "depasse le plafond global de memoire, donc a peu pres tout le temps. "
    "Dans les deux cas ce voyant ne coupe RIEN et ne bloque RIEN : c'est une etiquette. "
    "Il faut relancer Luciana apres avoir change ce fichier.")


def _lire_reglage_voyants():
    """Lit l'interrupteur UNE SEULE FOIS, au lancement (zero jeton, zero appel API).
    Le fichier est cree s'il n'existe pas. Si la lecture rate, on garde la v110 : un souci de
    fichier ne doit JAMAIS empecher Luciana de travailler."""
    try:
        if os.path.isfile(FICHIER_REGLAGE_VOYANTS):
            with open(FICHIER_REGLAGE_VOYANTS, encoding="utf-8-sig") as f:
                return bool((json.load(f) or {}).get("voyants_v110_actif", True))
    except Exception:
        return True
    try:
        with open(FICHIER_REGLAGE_VOYANTS, "w", encoding="utf-8") as f:
            json.dump({"voyants_v110_actif": True,
                       "_a_quoi_ca_sert": _EXPLICATION_REGLAGE_VOYANTS},
                      f, ensure_ascii=False, indent=2)
    except Exception:
        pass
    return True


VOYANTS_V110_ACTIF = _lire_reglage_voyants()


def voyant_memoire(refusees, consignes, total):
    """v110 : LA SEULE REGLE QUI ALLUME LE VOYANT JAUNE DU BANDEAU DE MEMOIRE. Elle est ici,
    toute seule, pour qu'on puisse la LIRE et la MESURER sans lancer tout le programme.
    Rend un couple (allume, quoi_faire). 'quoi_faire' est vide quand il n'y a rien a faire.
    Interrupteur eteint -> la v109, exactement, a la virgule pres.
    Cette fonction ne lit aucun fichier, n'ecrit rien, ne bloque rien : elle ne fait que choisir
    la couleur d'une etiquette."""
    try:
        refusees = int(refusees or 0)
        consignes = int(consignes or 0)
        total = int(total or 0)
    except Exception:
        # Meme avec des chiffres abimes, on n'inquiete pas pour rien et on ne casse pas le tour.
        return False, ""

    if not VOYANTS_V110_ACTIF:
        # LA v109, A UNE CHOSE PRES, ET C'EST L'ORDRE DE FRED DU 13/10/2026 : elle allumait
        # aussi le voyant quand 'total > MEMOIRE_CARACTERES_MAX'. Ce test est RETIRE, ici
        # comme ailleurs : il n'y a pas de plafond de memoire, donc un total ne peut pas
        # etre « trop grand », et il n'a plus a inquieter Fred pour rien. Les deux vraies
        # causes restent, elles : des regles importantes mises de cote, et le carnet de
        # regles plein. Rien n'est efface.
        allume = bool(refusees) or consignes > CONSIGNES_CARACTERES_MAX
        quoi = ""
        if refusees:
            quoi = (" : %d consigne(s) capitale(s) mise(s) de cote (gardee(s) sur le disque)"
                    % refusees)
        return allume, quoi

    # v110 : QUE les vrais problemes. Et quand on parle, on dit QUOI FAIRE, en une phrase.
    if refusees:
        return True, (" : %d de mes regles importantes ne me sont plus donnees en entier a "
                      "chaque message (elles restent entieres sur le disque, rien n'est perdu). "
                      "CE QU'IL FAUT FAIRE : dis-moi de ranger les regles qui sont terminees."
                      % refusees)
    if consignes > CONSIGNES_CARACTERES_MAX:
        return True, (" : mon carnet de regles est plein (%s caracteres au maximum par message). "
                      "CE QU'IL FAUT FAIRE : dis-moi de ranger les regles qui sont terminees."
                      % _en_car(CONSIGNES_CARACTERES_MAX))
    # TOUT LE RESTE : SILENCE. Un gros total est un etat NORMAL -- ce n'est PAS un plafond
    # depasse (il n'y a pas de plafond de memoire) : le programme se debrouille tout seul
    # avec la place de l'entete (il retrecit le detail des carnets), donc il se tait.
    return False, ""


# =====================================================================
#  CHANTIER DU 13/10/2026 (ordre de Fred, 03h00) — UN SEUL CHIFFRE, ET UN CHIFFRE JUSTE.
#
#  CE QUE FRED VOYAIT, ET SA PHRASE : « je vois 99 000, 148 231, 30 000, et je ne comprends
#  plus ». Il avait raison, et c'est pire que ca : la ligne affichait QUATRE nombres
#  (le total par message, le « plafond », les consignes, les souvenirs+carnets) et
#  AUCUN DES QUATRE ne mesurait sa bibliotheque. Tous les quatre mesuraient du DEBIT -- ce
#  qui part dans UN message -- et un debit change a chaque phrase qu'il tape. D'ou le
#  sentiment, parfaitement justifie, que les chiffres dansaient sans rien vouloir dire.
#
#  CE QU'IL Y A MAINTENANT : UN SEUL CHIFFRE, ET C'EST LE STOCK.
#  Tout ce qui est VRAIMENT garde dans sa memoire, lu sur les VRAIS FICHIERS du disque, a
#  l'instant ou on regarde. Pas un debit, pas un plafond, pas une moyenne, pas une
#  estimation : la somme du contenu reel de ses cinq fichiers de memoire.
#
#  LES CINQ FICHIERS COMPTES, ET RIEN D'AUTRE (ils sont nommes a l'ecran dans le detail) :
#     souvenirs.json         sa memoire longue (la liste de ses souvenirs)
#     luciana_memoire.json   le fil de toutes leurs conversations
#     bibliotheque2/arbre.json  la bibliotheque rangee par l'archiviste
#     consignes.jsonl        son carnet de regles
#     carnet.json            ses carnets de chantier
#
#  ON COMPTE LE CONTENU, PAS LE POIDS DU FICHIER : les accolades, les guillemets et les
#  noms de cases du JSON ne sont PAS de la memoire, et les compter gonflerait le chiffre
#  sans raison. Un fichier illisible est DIT, jamais devine.
# =====================================================================

def _car_dans(x):
    """Compte les caracteres de TEXTE dans n'importe quoi (texte, liste, dictionnaire),
    en descendant dedans. Les noms de cases du JSON ne comptent pas : ce n'est pas de la
    memoire, c'est de la plomberie. Ne leve jamais."""
    try:
        if x is None or isinstance(x, bool):
            return 0
        if isinstance(x, str):
            return len(x)
        if isinstance(x, (int, float)):
            return 0
        if isinstance(x, dict):
            return sum(_car_dans(v) for v in x.values())
        if isinstance(x, (list, tuple)):
            return sum(_car_dans(v) for v in x)
    except Exception:
        pass
    return 0


def _fichiers_de_la_memoire():
    """LES CINQ FICHIERS QUI CONTIENNENT LA MEMOIRE DE FRED, et rien d'autre.
    (nom court, chemin, forme du fichier, a quoi ca sert -- en francais, pour l'ecran)."""
    dossier_biblio2 = os.path.join(DOSSIER, "bibliotheque2")
    return [
        ("souvenirs", FICHIER_SOUVENIRS, "json",
         "ta memoire longue (tes souvenirs)"),
        ("conversations", FICHIER_MEMOIRE, "json",
         "le fil de toutes nos conversations"),
        ("bibliotheque", os.path.join(dossier_biblio2, "arbre.json"), "json",
         "ta bibliotheque rangee par l'archiviste"),
        ("regles", FICHIER_CONSIGNES, "jsonl",
         "ton carnet de regles"),
        ("carnets", FICHIER_CARNET, "json",
         "tes carnets de chantier"),
    ]


#  LE PETIT CACHE DE LA MESURE, ET IL EST LA POUR UNE RAISON PRECISE : le tableau de bord
#  interroge cette mesure EN BOUCLE, plusieurs fois par minute. Or luciana_memoire.json peut
#  peser plusieurs megaoctets : le relire et le re-analyser a chaque coup d'oeil ferait
#  ramer la machine pour rien -- exactement le defaut repare dans le chantier de la lenteur
#  (v165). On garde donc le dernier resultat, et on ne recalcule QUE si l'un des cinq
#  fichiers a bouge (sa date ou sa taille a change) et qu'au moins MESURE_REPOS secondes
#  sont passees. Regarder la date et la taille d'un fichier est immediat, ca ne l'ouvre pas.
_MESURE_REELLE_CACHE = {"signature": None, "quand": 0.0, "resultat": None}
MESURE_REELLE_REPOS = 5.0        # jamais deux calculs complets a moins de 5 secondes


def _signature_des_fichiers_memoire():
    """La date et la taille des cinq fichiers, en une seule chaine. Immediat, et il
    n'ouvre AUCUN fichier. Ne leve jamais."""
    bouts = []
    for nom, chemin, _forme, _legende in _fichiers_de_la_memoire():
        try:
            st = os.stat(chemin)
            bouts.append("%s:%d:%d" % (nom, st.st_size, int(st.st_mtime)))
        except Exception:
            bouts.append("%s:absent" % nom)
    return "|".join(bouts)


def mesure_de_la_memoire_reelle(forcer=False):
    """LE SEUL CHIFFRE DE MEMOIRE QUI VEUT DIRE QUELQUE CHOSE (13/10/2026, ordre de Fred).

    Rend le STOCK : tout ce qui est vraiment garde, lu sur les vrais fichiers, a l'instant.
    Rend un dictionnaire : {'total': ..., 'detail': {nom: caracteres}, 'fichiers': {nom:
    chemin}, 'illisibles': [...], 'absents': [...]}.

    LECTURE SEULE, ET ELLE NE MODIFIE RIEN. Elle ouvre cinq fichiers et les referme.
    Elle garde son dernier resultat de cote et ne recalcule que si un fichier a bouge
    (voir le cache juste au-dessus) : le tableau de bord peut donc l'appeler en boucle sans
    faire ramer la machine. 'forcer=True' recalcule quoi qu'il arrive.
    Ne leve JAMAIS : un fichier absent compte 0 et est dit absent, un fichier abime est dit
    illisible -- on ne devine pas un chiffre, jamais."""
    maintenant = time.time()
    signature = _signature_des_fichiers_memoire()
    if (not forcer and _MESURE_REELLE_CACHE["resultat"] is not None
            and (_MESURE_REELLE_CACHE["signature"] == signature
                 or maintenant - _MESURE_REELLE_CACHE["quand"] < MESURE_REELLE_REPOS)):
        return _MESURE_REELLE_CACHE["resultat"]

    fichiers = _fichiers_de_la_memoire()
    detail, chemins, a_quoi, illisibles, absents = {}, {}, {}, [], []
    for nom, chemin, forme, legende in fichiers:
        chemins[nom] = chemin
        a_quoi[nom] = legende
        detail[nom] = 0
        if not os.path.isfile(chemin):
            absents.append(nom)
            continue
        try:
            with open(chemin, encoding="utf-8-sig", errors="replace") as f:
                if forme == "jsonl":
                    total_lignes = 0
                    for ligne in f:
                        ligne = ligne.strip()
                        if not ligne:
                            continue
                        try:
                            total_lignes += _car_dans(json.loads(ligne))
                        except Exception:
                            total_lignes += len(ligne)   # la ligne est abimee : on compte
                    detail[nom] = total_lignes           # son texte brut, et on ne l'ignore pas
                else:
                    detail[nom] = _car_dans(json.load(f))
        except Exception:
            illisibles.append(nom)
            detail[nom] = 0
    resultat = {"total": sum(detail.values()), "detail": detail, "fichiers": chemins,
                "a_quoi": a_quoi, "illisibles": illisibles, "absents": absents,
                "quand": maintenant}
    _MESURE_REELLE_CACHE.update(signature=signature, quand=maintenant, resultat=resultat)
    return resultat


def mesure_memoire():
    """v97 : LE COMPTE DE LA MEMOIRE, pour que Fred le LISE A L'ECRAN sans rien demander.

    13/10/2026 (ordre de Fred) — CE QUI A CHANGE : LA LIGNE AFFICHEE N'A PLUS QU'UN CHIFFRE.
    AVANT, elle en affichait quatre, et aucun des quatre ne mesurait sa bibliotheque :
       "Memoire : 99 000 car. par message (plafond 150 000) - consignes 30 000 / 30 000 -
        souvenirs+carnets 69 000 - OK"
    Les quatre mesuraient du DEBIT : ce qui part dans UN message. Un debit change a chaque
    phrase tapee, d'ou des chiffres qui dansaient sans rien vouloir dire.
    APRES, elle affiche LE STOCK, et lui seul :
       "Memoire : 2 480 112 caracteres gardes — c'est TOUT ce qui est vraiment dans ta
        memoire sur le disque, a l'instant (...). Rien n'est jamais efface. — OK"
    Ce chiffre est calcule par mesure_de_la_memoire_reelle(), sur les VRAIS FICHIERS
    (souvenirs.json, luciana_memoire.json, bibliotheque2/arbre.json, consignes.jsonl,
    carnet.json). Si l'un d'eux est illisible, la ligne le DIT.

    LES ANCIENS CHIFFRES NE SONT PAS PERDUS : ils restent tous dans le dictionnaire rendu,
    donc dans le journal et dans le depannage. C'est l'AFFICHAGE qui est nettoye, pas la
    mesure. Ce qui est compte pour eux, comme avant : les consignes (relues sur le disque a
    l'instant, c'est leger : un seul fichier texte) + la derniere mesure reelle des souvenirs
    et des carnets envoyes au dernier message (_MESURE_MEMOIRE, remplie par repondre()).

    Cette fonction NE MODIFIE RIEN : elle ne touche ni aux fichiers, ni aux compteurs du
    tour en cours."""
    try:
        _t = texte_consignes_v180()          # V180 : la partie fixe du carnet, sans tri
        m = {"contenu": len(_t), "apres": len(_t), "capitales_refusees": 0}
    except Exception:
        m = {}
    consignes = int(m.get("contenu") or 0)            # le POIDS des consignes elles-memes
    envoye_consignes = int(m.get("apres") or 0)       # ... avec les explications du programme
    refusees = int(m.get("capitales_refusees") or 0)
    souvenirs = int(_MESURE_MEMOIRE.get("souvenirs") or 0)
    carnets = int(_MESURE_MEMOIRE.get("carnets") or 0)
    total = envoye_consignes + souvenirs + carnets
    # v110 : LE VOYANT. La regle est toute seule dans voyant_memoire() juste au-dessus.
    # 13/10/2026 : un total ne peut plus allumer le voyant, dans AUCUN des deux cas -- il n'y
    # a pas de plafond de memoire. Le voyant n'a plus que deux causes, et ce sont des vraies :
    # des regles importantes mises de cote, ou le carnet de regles plein.
    a_trier, quoi_faire = voyant_memoire(refusees, consignes, total)
    etat = ("A TRIER" if a_trier else "OK") + quoi_faire

    # =====================================================================
    #  13/10/2026 (ordre de Fred) : LA LIGNE N'AFFICHE PLUS QU'UN SEUL CHIFFRE, ET C'EST
    #  LE STOCK REEL -- ce qu'il y a VRAIMENT dans sa memoire, lu sur ses vrais fichiers.
    #  LES QUATRE ANCIENS NOMBRES (le total par message « 99 000 », le « plafond 150 000 »,
    #  les consignes « 30 000 », les souvenirs+carnets) SONT RETIRES DE L'ECRAN : ils
    #  mesuraient tous du DEBIT, aucun ne mesurait sa bibliotheque, et c'est exactement ce
    #  qu'il reprochait. Ils restent tous dans le dictionnaire rendu ci-dessous, donc dans
    #  couts_appels.jsonl et dans le depannage : rien n'est perdu, c'est l'AFFICHAGE qui est
    #  nettoye.
    # =====================================================================
    try:
        reel = mesure_de_la_memoire_reelle()
    except Exception:
        reel = {"total": 0, "detail": {}, "illisibles": ["(mesure impossible)"], "absents": []}
    dit_le_souci = ""
    if reel.get("illisibles"):
        # ON LE DIT, on ne fait pas passer un chiffre incomplet pour un chiffre juste.
        dit_le_souci = (" (et je le dis : %s illisible(s), donc ce chiffre est incomplet)"
                        % ", ".join(reel["illisibles"]))
    ligne = ("Memoire : %s caracteres gardes — c'est TOUT ce qui est vraiment dans ta "
             "memoire sur le disque, a l'instant (tes souvenirs, nos conversations, ta "
             "bibliotheque rangee, tes regles, tes carnets). Rien n'est jamais efface.%s — %s"
             % (_en_car(reel.get("total") or 0), dit_le_souci, etat))

    return {"ligne": ligne, "a_trier": a_trier, "quoi_faire": quoi_faire,
            "voyants_v110": VOYANTS_V110_ACTIF,
            # LE CHIFFRE JUSTE, et de quoi il est fait, fichier par fichier.
            "memoire_reelle": reel.get("total") or 0,
            "memoire_reelle_detail": reel.get("detail") or {},
            "memoire_reelle_fichiers": reel.get("fichiers") or {},
            "memoire_reelle_illisibles": reel.get("illisibles") or [],
            "memoire_reelle_absents": reel.get("absents") or [],
            # LES ANCIENS CHIFFRES : gardes pour le journal et le depannage, PLUS AFFICHES.
            # Ils mesurent le DEBIT d'un message, jamais la memoire.
            "total": total, "consignes": consignes,
            "consignes_envoyees": envoye_consignes, "souvenirs": souvenirs, "carnets": carnets,
            "capitales_refusees": refusees,
            "budget_entete": BUDGET_ENTETE_CARACTERES,
            "plafond": BUDGET_ENTETE_CARACTERES,   # alias garde : plus jamais affiche
            "plafond_consignes": CONSIGNES_CARACTERES_MAX,
            "carnet_entier_sur_le_disque": int(m.get("avant") or 0)}


# =====================================================================
#  v99 (c) : LE COMPTEUR "TU NE M'AS PAS REPONDU" (demande de Fred, 03/10/2026 a 21h40).
#  POURQUOI : quand Fred explique son raisonnement, la corrige ou lui reproche quelque chose, elle
#  repondait "c'est note, je le garde" au lieu de repondre sur le fond, et Fred devait insister une
#  DEUXIEME fois. Pour savoir si ca s'arrange ou si ca empire, il faut un CHIFFRE, pas une impression.
#  QUI COMPTE : LE PROGRAMME, a la reception du message de Fred. Pas Luciana : elle ne peut ni
#  l'oublier, ni l'arrondir, ni se noter une bonne note toute seule.
#  CE QUI EST COMPTE : seulement les phrases ou Fred DIT qu'elle n'a pas repondu ("tu ne m'as pas
#  repondu", "a cote de la plaque", "c'est pas ca"). Pas les corrections en general : ce compteur
#  repond a UNE question, "combien de fois a-t-il fallu que j'insiste ?".
#  OU C'EST ECRIT : un petit fichier a part (compteur_pas_repondu.json) : le chiffre survit a un F5,
#  a un redemarrage, et il ne touche a aucun autre fichier de memoire.
#  OU C'EST VU : en petit, a cote de la ligne "Memoire : ...", meme endroit, meme style (v97).
# =====================================================================
FICHIER_PAS_REPONDU = os.path.join(DOSSIER, "compteur_pas_repondu.json")
_verrou_pas_repondu = threading.Lock()

# Les phrases de Fred qui veulent dire "tu n'as pas repondu". Ecrites SANS accents : le texte est
# passe a _sans_accents() avant la comparaison, donc "répondu" et "repondu" marchent tous les deux.
_MOTS_PAS_REPONDU = re.compile(
    r"(tu ne m'?as (toujours )?pas repondu|tu (ne )?reponds pas|t'?as pas repondu"
    r"|pas repondu a ma question|tu n'?as pas repondu"
    r"|a cote de la plaque|c'?est pas ca|ce n'?est pas ca|c'?est pas (du tout )?ce que"
    r"|je t'?ai deja dit|je te l'?ai deja dit)")


def _dit_que_je_n_ai_pas_repondu(texte):
    """Vrai si Fred dit, dans CE message, qu'elle n'a pas repondu. Les messages automatiques du
    programme (ils commencent par '[') ne comptent jamais : ce n'est pas Fred qui parle."""
    t = (texte or "").strip()
    if not t or t.startswith("["):
        return False
    return bool(_MOTS_PAS_REPONDU.search(_sans_accents(t)))


def _lire_pas_repondu():
    d = _charger_json_sur(FICHIER_PAS_REPONDU, {})
    return d if isinstance(d, dict) else {}


def noter_si_pas_repondu(texte):
    """Appele par le programme a CHAQUE message de Fred. Si Fred dit qu'elle n'a pas repondu, le
    compteur monte de 1 et on garde la date + le debut de sa phrase (pour la preuve, sur du reel).
    Rend le nombre total. N'ecrit rien si la phrase ne correspond pas : aucun fichier touche."""
    if not _dit_que_je_n_ai_pas_repondu(texte):
        return int(_lire_pas_repondu().get("combien") or 0)
    with _verrou_pas_repondu:
        d = _lire_pas_repondu()
        combien = int(d.get("combien") or 0) + 1
        d["combien"] = combien
        d["dernier_quand"] = time.strftime("%d/%m/%Y a %Hh%M")
        d["dernier_texte"] = (texte or "").strip()[:200]
        d.setdefault("depuis", time.strftime("%d/%m/%Y a %Hh%M"))
        try:
            tmp = FICHIER_PAS_REPONDU + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(d, f, ensure_ascii=False, indent=1)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp, FICHIER_PAS_REPONDU)
        except Exception:
            pass
    return combien


def compte_pas_repondu():
    """Ce qui est AFFICHE a Fred, a cote de la ligne 'Memoire : ...'. Ne modifie rien."""
    d = _lire_pas_repondu()
    combien = int(d.get("combien") or 0)
    if combien <= 0:
        ligne = "Reponses a cote : 0 depuis la remise a zero."
    else:
        ligne = ("Reponses a cote : %d fois ou tu as dit que je n'avais pas repondu%s."
                 % (combien, (" (la derniere le %s)" % d["dernier_quand"]) if d.get("dernier_quand") else ""))
    return {"combien": combien, "ligne": ligne, "a_trier": combien > 0,
            "dernier_quand": d.get("dernier_quand", ""), "dernier_texte": d.get("dernier_texte", ""),
            "depuis": d.get("depuis", "")}


def remettre_a_zero_pas_repondu():
    """L'action simple demandee par Fred : le compteur repart de 0. L'ancien chiffre n'est pas
    efface en douce : il est garde dans le meme fichier (avant_remise_a_zero), date."""
    with _verrou_pas_repondu:
        d = _lire_pas_repondu()
        avant = int(d.get("combien") or 0)
        historique = d.get("remises") if isinstance(d.get("remises"), list) else []
        historique.append({"combien": avant, "quand": time.strftime("%d/%m/%Y a %Hh%M")})
        neuf = {"combien": 0, "depuis": time.strftime("%d/%m/%Y a %Hh%M"),
                "remises": historique[-20:]}
        try:
            tmp = FICHIER_PAS_REPONDU + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump(neuf, f, ensure_ascii=False, indent=1)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp, FICHIER_PAS_REPONDU)
        except Exception as ex:
            return {"ok": False, "avant": avant, "err": str(ex)[:200]}
    return {"ok": True, "avant": avant}


def outil_consigne(e):
    """Le carnet de consignes : ajouter, corriger, lister, oublier. Le fichier n'est jamais reecrit."""
    action = _sans_accents(str(e.get("action") or "ajouter")).strip()
    texte = str(e.get("texte") or "").strip()
    importance = _sans_accents(str(e.get("importance") or "")).strip()
    importance = "capitale" if importance.startswith("capital") else "normale"
    try:
        numero = int(e.get("numero") or 0)
    except Exception:
        numero = 0
    actives = consignes_actives()

    def _retrouver():
        """Retrouve une consigne par son numero, ou a defaut par un bout de son texte."""
        if numero:
            for c in actives:
                if c["numero"] == numero:
                    return c, ""
            return None, ("Je n'ai pas de consigne active n%d. Mes consignes actives : %s." % (
                numero, ", ".join("n%d" % c["numero"] for c in actives) or "aucune"))
        reperes = _sans_accents(str(e.get("repere") or texte))
        if not reperes:
            return None, "Dis-moi quelle consigne (son numero, ou un bout de son texte)."
        trouvees = [c for c in actives if reperes in _sans_accents(c["texte"])]
        if not trouvees:
            return None, ("Aucune consigne active ne parle de '%s'. Mes consignes actives : %s." % (
                e.get("repere") or texte,
                " / ".join("n%d %s" % (c["numero"], c["texte"][:60]) for c in actives) or "aucune"))
        if len(trouvees) > 1:
            return None, ("Plusieurs consignes correspondent : %s. Donne-moi le numero." % ", ".join(
                "n%d (%s)" % (c["numero"], c["texte"][:60]) for c in trouvees))
        return trouvees[0], ""

    if action.startswith("list"):
        total_lignes = len(_lire_lignes_jsonl(FICHIER_CONSIGNES))
        if not actives:
            return ("Mon carnet de consignes est vide pour l'instant (fichier %s). Dis-moi 'retiens "
                    "cette consigne : ...' et je l'y ecris tout de suite." % FICHIER_CONSIGNES)
        corps = "\n".join("- n%d (note le %s%s)%s : %s" % (
            c["numero"], _jj_mm(c.get("date")),
            ", corrigee le %s" % _jj_mm(c["corrigee"]) if c.get("corrigee") else "",
            " [IMPORTANT]" if _est_capitale(c) else "", c["texte"]) for c in actives)
        return ("%d consigne(s) active(s), dans %s (%d ligne(s) ecrites en tout : le fichier ne se "
                "reecrit jamais, il s'ajoute) :\n%s" % (
                    len(actives), FICHIER_CONSIGNES, total_lignes, corps))

    if action.startswith("ajout") or action.startswith("note") or action.startswith("ecri"):
        if not texte:
            return "Dis-moi la consigne a ecrire dans mon carnet."
        deja = [c for c in actives if _sans_accents(c["texte"]) == _sans_accents(texte)]
        if deja:
            return "Cette consigne est deja dans mon carnet (n%d), je ne la mets pas en double." % deja[0]["numero"]
        num = _prochain_numero(FICHIER_CONSIGNES)
        # 13/10/2026, TRAVAIL 1 (meme famille que le [:40] du sens) : c'etait « texte[:4000] ».
        # Une consigne longue de Fred etait donc ECRITE COUPEE sur le disque, et la fin etait
        # perdue pour de bon -- sans que rien ne le dise. La consigne est maintenant gardee EN
        # ENTIER. Rien ne risque de gonfler le message : ce qui part a chaque message est deja
        # borne ailleurs, par CONSIGNES_CARACTERES_MAX, et une consigne trop longue y est
        # abregee a l'affichage AVEC la phrase qui dit de l'ouvrir en entier (action 'ouvrir').
        _ajouter_ligne_jsonl(FICHIER_CONSIGNES, {
            "date": time.strftime("%Y-%m-%d %H:%M"), "action": "ajouter", "numero": num,
            "texte": texte, "importance": importance})
        reponse = ("Consigne n%d ecrite pour de vrai dans %s. Je la relis a CHAQUE message a partir "
                   "de maintenant, et elle ne disparaitra que si tu me demandes de la retirer." % (
                       num, FICHIER_CONSIGNES))
        # v97 : on ne laisse pas croire que tout est donne en entier quand le plafond est plein.
        # Dire la verite tout de suite vaut mieux que de le decouvrir en repondant a cote.
        try:
            m = {}                               # V180 : plus de tri, donc plus de capitale refusee
            if m.get("capitales_refusees"):
                reponse += (" ATTENTION : LE PLAFOND DES CONSIGNES EST PLEIN (%d car. au maximum par "
                            "message). %d consigne(s) capitale(s) (n%s) ne me sont PLUS donnees en "
                            "entier a chaque message — elles restent entieres sur le disque, rien "
                            "n'est perdu. Si ce qui vient d'etre ecrit doit vraiment passer avant, il "
                            "faut TRIER : degrade une capitale en normale (action 'corriger', "
                            "importance 'normale'), ou range ce qui est termine (action 'ranger')." % (
                                CONSIGNES_CARACTERES_MAX, m["capitales_refusees"],
                                ", n".join(str(n) for n in m.get("refusees") or [])))
        except Exception:
            pass
        return reponse

    if action.startswith("corrig") or action.startswith("modif"):
        if not texte:
            return "Dis-moi le nouveau texte de la consigne."
        if not numero and not str(e.get("repere") or "").strip():
            # Sans repere, on chercherait le NOUVEAU texte parmi les anciennes : ca ne trouve rien.
            return ("Dis-moi LAQUELLE je corrige : son numero, ou un bout de son ancien texte "
                    "('repere'). Mes consignes actives : %s." % (
                        " / ".join("n%d %s" % (c["numero"], c["texte"][:60]) for c in actives)
                        or "aucune"))
        c, souci = _retrouver()
        if not c:
            return souci
        _ajouter_ligne_jsonl(FICHIER_CONSIGNES, {
            # 13/10/2026, TRAVAIL 1 : c'etait « texte[:4000] ». Le nouveau texte d'une consigne
            # corrigee est maintenant ecrit EN ENTIER, comme a l'ajout.
            "date": time.strftime("%Y-%m-%d %H:%M"), "action": "corriger", "numero": c["numero"],
            "texte": texte, "importance": importance if importance == "capitale" else c.get("importance")})
        return ("Consigne n%d corrigee pour de vrai. L'ancien texte reste ecrit dans le fichier (il "
                "n'est jamais efface) : \"%s\"." % (c["numero"], c["texte"][:200]))

    if action.startswith("oubli") or action.startswith("retir") or action.startswith("suppr"):
        c, souci = _retrouver()
        if not c:
            return souci
        _ajouter_ligne_jsonl(FICHIER_CONSIGNES, {
            # 13/10/2026, TRAVAIL 1 : c'etait « c["texte"][:4000] ». La trace de ce qui est
            # retire garde maintenant le texte EN ENTIER : on peut toujours tout relire.
            "date": time.strftime("%Y-%m-%d %H:%M"), "action": "oublier", "numero": c["numero"],
            "texte": c["texte"]})
        return ("Consigne n%d retiree de mon carnet : je ne l'applique plus. Son texte reste ecrit "
                "dans le fichier, donc on peut toujours la relire : \"%s\"." % (
                    c["numero"], c["texte"][:200]))

    # v94 : OUVRIR UNE CONSIGNE EN ENTIER. Dans le prompt, les consignes normales tiennent sur UNE
    # ligne (voir texte_consignes) : cette action rend le texte EXACT, mot pour mot, depuis le
    # fichier. Rien n'a jamais ete perdu, c'est juste l'affichage du prompt qui est allege.
    if (action.startswith("ouvr") or action.startswith("voir") or action.startswith("lire")
            or action.startswith("relire") or action.startswith("montre")):
        c, souci = _retrouver()
        if not c:
            return souci
        return ("Consigne n%d, EN ENTIER (texte exact, relu dans %s)%s :\n%s" % (
            c["numero"], FICHIER_CONSIGNES,
            " [IMPORTANT]" if _est_capitale(c) else "", c["texte"]))

    # v97 : RANGER LES CONSIGNES "EN REPOS". Sans 'appliquer', ca ne fait que MONTRER la liste :
    # rien n'est touche. Avec 'appliquer', les consignes designees passent dans un fichier a part
    # et quittent le carnet actif — leur texte reste ecrit DEUX fois sur le disque, rien n'est efface.
    if action.startswith("rang") or action.startswith("tri"):
        return ranger_consignes_en_repos(appliquer=bool(e.get("appliquer")))

    return ("Action inconnue '%s'. Actions : ajouter, corriger, lister, ouvrir, oublier, ranger." % action)


# =====================================================================
#  v97 : LA MEMOIRE PROPRE — ranger ce qui DORT, sans jamais rien effacer.
#  POURQUOI : un carnet qui ne fait que grossir finit par remplir le plafond avec des consignes
#  qui ne servent plus (un bug repare en septembre, un chantier termine, une date passee). Tant
#  qu'elles sont la, ce sont les consignes VIVANTES qui se font refuser par le plafond.
#  CE QUE CA FAIT, EXACTEMENT :
#   - sans 'appliquer' : ca ne fait que MONTRER la liste des candidates et dire pourquoi. AUCUNE
#     ecriture, aucun fichier touche. C'est le mode par defaut.
#   - avec 'appliquer' : chaque consigne designee est (1) RECOPIEE dans consignes_en_repos.jsonl,
#     puis (2) retiree du carnet ACTIF par une ligne "oublier" ajoutee a la fin de consignes.jsonl.
#     Les deux fichiers ne font que GROSSIR : la ligne d'origine, avec son texte entier, reste
#     ecrite dans consignes.jsonl pour toujours. RIEN N'EST SUPPRIME DU DISQUE, jamais.
#  CE QUI N'EST PAS FAIT ICI, ET C'EST VOULU : rien ne lance cette fonction tout seul. Fred a
#  demande que la fonction EXISTE et soit appelable (outil 'consigne', action 'ranger') ; son
#  demarrage automatique (par exemple a un point du soir) sera decide par lui, pas par le code.
# =====================================================================
_MOTS_EN_REPOS = ("bug repare", "bug corrige", "c'est repare", "c'est corrige", "deja repare",
                  "chantier termine", "chantier fini", "projet clos", "projet termine",
                  "projet abandonne", "affaire classee", "plus la peine", "n'est plus d'actualite",
                  "plus d'actualite", "ca ne sert plus", "ne sert plus a rien", "obsolete")
_MOTS_ECHEANCE = ("jusqu'au", "jusqu'a", "avant le", "d'ici le", "pour le", "au plus tard le",
                  "le temps de", "cette semaine", "ce week-end")
_DATE_DANS_TEXTE = re.compile(r"(\d{4})-(\d{2})-(\d{2})|(\d{1,2})/(\d{1,2})/(\d{4})")


def _dates_du_texte(texte):
    """Les dates ecrites dans un texte, en AAAA-MM-JJ (les deux facons d'ecrire : 2026-10-03 et
    03/10/2026). Sert a reperer une consigne dont l'echeance est DEJA PASSEE."""
    trouvees = []
    for m in _DATE_DANS_TEXTE.finditer(str(texte or "")):
        if m.group(1):
            trouvees.append("%s-%s-%s" % (m.group(1), m.group(2), m.group(3)))
        else:
            trouvees.append("%s-%02d-%02d" % (m.group(6), int(m.group(5)), int(m.group(4))))
    return trouvees


def consignes_en_repos(aujourd_hui=None):
    """Les consignes qui DORMENT, avec la raison de chacune. On ne DESIGNE, on ne touche a rien.
    Deux seuls motifs, volontairement prudents (mieux vaut en oublier une que ranger une consigne
    encore vivante) :
      - son texte dit clairement que c'est fini ("bug repare", "chantier termine", "projet clos") ;
      - son texte porte une ECHEANCE ("jusqu'au...", "avant le...") et TOUTES les dates qu'il
        contient sont DEJA PASSEES."""
    jour = aujourd_hui or time.strftime("%Y-%m-%d")
    dorment = []
    for c in consignes_actives():
        t = _sans_accents(c.get("texte") or "")
        raison = ""
        for mot in _MOTS_EN_REPOS:
            if _sans_accents(mot) in t:
                raison = "son texte dit que c'est termine (\"%s\")" % mot
                break
        if not raison and any(_sans_accents(mot) in t for mot in _MOTS_ECHEANCE):
            dates = [d for d in _dates_du_texte(c.get("texte")) if d < DATE_SANS_LIMITE]
            if dates and all(d < jour for d in dates):
                raison = "son echeance est passee (%s, et nous sommes le %s)" % (", ".join(dates), jour)
        if raison:
            dorment.append((c, raison))
    return dorment


def ranger_consignes_en_repos(appliquer=False, aujourd_hui=None):
    """Range les consignes "en repos" dans consignes_en_repos.jsonl, SANS RIEN EFFACER (voir le
    grand commentaire au-dessus). appliquer=False (defaut) : on ne fait que dire ce qui serait
    range, sans ecrire une seule ligne."""
    dorment = consignes_en_repos(aujourd_hui)
    if not dorment:
        return ("Rien a ranger : aucune de mes consignes actives ne dit qu'elle est terminee, et "
                "aucune n'a d'echeance deja passee. Le carnet reste tel quel.")
    liste = "\n".join("- n%d (%s) : %s" % (c["numero"], raison, c["texte"][:160])
                      for c, raison in dorment)
    if not appliquer:
        return ("%d consigne(s) dorment et pourraient etre rangees (JE N'AI RIEN TOUCHE) :\n%s\n"
                "Pour les ranger pour de vrai : outil 'consigne', action 'ranger', appliquer = vrai. "
                "Elles seront recopiees dans %s et quitteront le carnet actif ; leur texte restera "
                "ecrit dans %s, mot pour mot : rien n'est supprime." % (
                    len(dorment), liste, FICHIER_CONSIGNES_REPOS, FICHIER_CONSIGNES))
    rangees, soucis = [], []
    for c, raison in dorment:
        try:
            # 1) on la RECOPIE (le fichier de repos ne fait que grossir)
            _ajouter_ligne_jsonl(FICHIER_CONSIGNES_REPOS, {
                "date": time.strftime("%Y-%m-%d %H:%M"), "action": "rangee", "numero": c["numero"],
                "texte": c["texte"], "importance": c.get("importance") or "normale",
                "date_origine": c.get("date") or "", "raison": raison})
            # 2) puis on la sort du carnet ACTIF : une ligne AJOUTEE a la fin, rien de reecrit.
            _ajouter_ligne_jsonl(FICHIER_CONSIGNES, {
                "date": time.strftime("%Y-%m-%d %H:%M"), "action": "oublier", "numero": c["numero"],
                "texte": c["texte"], "rangee_dans": FICHIER_CONSIGNES_REPOS, "raison": raison})
            rangees.append(c["numero"])
        except Exception as ex:
            soucis.append("n%d (%s)" % (c["numero"], str(ex)[:120]))
    bilan = ("%d consigne(s) rangee(s) : n%s. Elles sont recopiees dans %s et ne sont plus dans le "
             "carnet actif. RIEN N'A ETE SUPPRIME : leur texte entier reste ecrit dans %s." % (
                 len(rangees), ", n".join(str(n) for n in rangees) or "-",
                 FICHIER_CONSIGNES_REPOS, FICHIER_CONSIGNES))
    if soucis:
        bilan += " ATTENTION, je n'ai pas pu ranger : %s." % " / ".join(soucis)
    return bilan


# ---------- la liste "ne plus m'en parler" ----------
def sujets_a_eviter_actifs(aujourd_hui=None):
    """Les sujets encore valables aujourd'hui. Une ligne dont la date d'expiration est passee
    disparait TOUTE SEULE de cette liste (elle reste ecrite dans le fichier)."""
    jour = aujourd_hui or time.strftime("%Y-%m-%d")
    vivants = {}
    for d in _lire_lignes_jsonl(FICHIER_SUJETS_EVITES):
        try:
            num = int(d.get("numero") or 0)
        except Exception:
            num = 0
        if not num:
            continue
        action = _sans_accents(str(d.get("action") or "ajouter")).strip()
        if action.startswith("retir") or action.startswith("oubli") or action.startswith("suppr"):
            vivants.pop(num, None)
            continue
        sujet = str(d.get("sujet") or "").strip()
        if not sujet:
            continue
        vivants[num] = {"numero": num, "sujet": sujet, "date": str(d.get("date") or ""),
                        "jusqu_au": str(d.get("jusqu_au") or DATE_SANS_LIMITE)}
    return [vivants[n] for n in sorted(vivants) if vivants[n]["jusqu_au"] >= jour]


def outil_sujet_a_eviter(e):
    """La liste 'ne plus m'en parler' : ajouter (avec une duree facultative), lister, retirer."""
    action = _sans_accents(str(e.get("action") or "ajouter")).strip()
    sujet = str(e.get("sujet") or "").strip()
    actifs = sujets_a_eviter_actifs()

    if action.startswith("list"):
        total = len(_lire_lignes_jsonl(FICHIER_SUJETS_EVITES))
        if not actifs:
            return ("Il n'y a aucun sujet a eviter en ce moment (fichier %s, %d ligne(s) ecrites en "
                    "tout, dont les expirees)." % (FICHIER_SUJETS_EVITES, total))
        corps = "\n".join("- n%d : %s (%s, note le %s)" % (
            s["numero"], s["sujet"], _date_en_clair(s.get("jusqu_au")), _jj_mm(s.get("date")))
            for s in actifs)
        return "%d sujet(s) dont je ne parle plus :\n%s" % (len(actifs), corps)

    if action.startswith("retir") or action.startswith("oubli") or action.startswith("suppr"):
        try:
            numero = int(e.get("numero") or 0)
        except Exception:
            numero = 0
        choisi = None
        if numero:
            choisi = next((s for s in actifs if s["numero"] == numero), None)
        elif sujet:
            repere = _sans_accents(sujet)
            trouves = [s for s in actifs if repere in _sans_accents(s["sujet"])]
            if len(trouves) > 1:
                return "Plusieurs sujets correspondent : %s. Donne-moi le numero." % ", ".join(
                    "n%d (%s)" % (s["numero"], s["sujet"]) for s in trouves)
            choisi = trouves[0] if trouves else None
        if not choisi:
            return ("Je ne trouve pas ce sujet dans ma liste. Ce que j'ai : %s." % (
                " / ".join("n%d %s" % (s["numero"], s["sujet"]) for s in actifs) or "rien"))
        _ajouter_ligne_jsonl(FICHIER_SUJETS_EVITES, {
            "date": time.strftime("%Y-%m-%d %H:%M"), "action": "retirer",
            "numero": choisi["numero"], "sujet": choisi["sujet"]})
        return "C'est retire : je peux de nouveau te parler de %s." % choisi["sujet"]

    if action.startswith("ajout") or action.startswith("evit") or action.startswith("note"):
        if not sujet:
            return "Dis-moi de quel sujet je ne dois plus te parler."
        jours = e.get("jours")
        if jours is None or str(jours).strip() == "":
            jours = _duree_en_jours(e.get("duree"))
        else:
            try:
                jours = int(jours)
            except Exception:
                jours = _duree_en_jours(e.get("duree"))
        jusqu_au = _lire_date(e.get("jusqu_au"))
        if not jusqu_au:
            if jours is None:
                jours = JOURS_PAR_DEFAUT_SUJET
            jusqu_au = DATE_SANS_LIMITE if jours < 0 else _date_dans(jours)
        deja = [s for s in actifs if _sans_accents(s["sujet"]) == _sans_accents(sujet)]
        num = deja[0]["numero"] if deja else _prochain_numero(FICHIER_SUJETS_EVITES)
        _ajouter_ligne_jsonl(FICHIER_SUJETS_EVITES, {
            "date": time.strftime("%Y-%m-%d %H:%M"), "action": "ajouter", "numero": num,
            "sujet": sujet[:1000], "jusqu_au": jusqu_au})
        return ("C'est note pour de vrai (%s, ligne n%d) : je ne te parle plus de %s, %s. Je ne "
                "relancerai pas le sujet de moi-meme ; si c'est toi qui m'en parles, je te reponds "
                "normalement. Passe cette date, la ligne disparait toute seule." % (
                    FICHIER_SUJETS_EVITES, num, sujet, _date_en_clair(jusqu_au)))

    return "Action inconnue '%s'. Actions : ajouter, lister, retirer." % action


