# =====================================================================================
#  V180 : GEMINI DANS LE MENU DES CERVEAUX.
#  DeepSeek et Claude parlent la meme langue (celle de la bibliotheque anthropic). Gemini non :
#  cette "prise" traduit, dans les deux sens, entre ce que le programme envoie deja et l'adresse
#  compatible de Google (generativelanguage.googleapis.com/v1beta/openai). Le reste du programme
#  ne voit aucune difference : memes outils, meme boucle, memes compteurs de cout.
#  LA CLE : ~/Luciana/cle_gemini.txt, ou a defaut la cle « gemini » du panneau Cles
#  (cles_services.json). LE NOM EXACT DU MODELE : GEMINI_MODELE_DEFAUT ci-dessous, ou celui ecrit
#  dans ~/Luciana/gemini_modele.txt (pour suivre Google sans toucher au code).
#  ATTENTION, DIT FRANCHEMENT : cette prise n'a PAS pu etre essayee contre le vrai Gemini depuis
#  la session de codage (pas de cle, pas d'acces). Son premier vrai appel se fait chez Fred.
# =====================================================================================
GEMINI_URL = "https://generativelanguage.googleapis.com/v1beta/openai/chat/completions"
GEMINI_MODELE_DEFAUT = "gemini-3.8-flash"
FICHIER_CLE_GEMINI = os.path.join(DOSSIER, "cle_gemini.txt")
FICHIER_MODELE_GEMINI = os.path.join(DOSSIER, "gemini_modele.txt")


def lire_cle_gemini():
    try:
        for ligne in open(FICHIER_CLE_GEMINI, encoding="utf-8-sig").read().splitlines():
            if ligne.strip().startswith("AIza"):
                return ligne.strip()
    except Exception:
        pass
    try:
        for nom, conf in (charger_cles_services() or {}).items():
            if "gemini" in str(nom).lower() and isinstance(conf, dict) and conf.get("cle"):
                return str(conf["cle"]).strip()
    except Exception:
        pass
    return None


def definir_cle_gemini(nouvelle):
    nouvelle = (nouvelle or "").strip()
    if not nouvelle.startswith("AIza"):
        return False, "Cette cle ne ressemble pas a une cle Gemini (elle commence par AIza)."
    try:
        with open(FICHIER_CLE_GEMINI, "w", encoding="utf-8") as f:
            f.write(nouvelle)
        return True, ""
    except Exception as e:
        return False, str(e)


def modele_gemini():
    try:
        t = open(FICHIER_MODELE_GEMINI, encoding="utf-8-sig").read().strip()
        if t:
            return t
    except Exception:
        pass
    return GEMINI_MODELE_DEFAUT


class _GBloc:
    def __init__(self, **kw):
        self.__dict__.update(kw)

    def model_dump(self):
        d = {k: v for k, v in self.__dict__.items() if not k.startswith("_")}
        return d


class _GReponse:
    def __init__(self, contenu, stop, usage):
        self.content = contenu
        self.stop_reason = stop
        self.usage = usage


def _g_texte_du_contenu(c):
    if isinstance(c, str):
        return c
    morceaux = []
    for b in (c or []):
        if isinstance(b, dict):
            if b.get("type") == "text":
                morceaux.append(str(b.get("text") or ""))
        elif getattr(b, "type", "") == "text":
            morceaux.append(str(getattr(b, "text", "") or ""))
    return "\n".join(morceaux)


def _g_messages(system, messages):
    """Anthropic -> format compatible de Google."""
    sortie = []
    sys_txt = _g_texte_du_contenu(system) if not isinstance(system, str) else system
    if sys_txt:
        sortie.append({"role": "system", "content": sys_txt})
    for m in messages or []:
        role, c = m.get("role"), m.get("content")
        if isinstance(c, str):
            sortie.append({"role": "assistant" if role == "assistant" else "user", "content": c})
            continue
        if role == "assistant":
            texte, appels = [], []
            for b in c or []:
                t = b.get("type") if isinstance(b, dict) else getattr(b, "type", "")
                if t == "text":
                    texte.append(str((b.get("text") if isinstance(b, dict) else b.text) or ""))
                elif t == "tool_use":
                    brut = getattr(b, "_brut", None) if not isinstance(b, dict) else b.get("_brut")
                    if brut:
                        appels.append(brut)
                    else:
                        appels.append({"id": b["id"] if isinstance(b, dict) else b.id, "type": "function",
                                       "function": {"name": b["name"] if isinstance(b, dict) else b.name,
                                                    "arguments": json.dumps((b["input"] if isinstance(b, dict) else b.input) or {},
                                                                            ensure_ascii=False)}})
            msg = {"role": "assistant", "content": "\n".join(texte) or None}
            if appels:
                msg["tool_calls"] = appels
            sortie.append(msg)
            continue
        parts, images_des_outils = [], []
        for b in c or []:
            if not isinstance(b, dict):
                continue
            t = b.get("type")
            if t == "text":
                parts.append({"type": "text", "text": str(b.get("text") or "")})
            elif t == "image":
                src = b.get("source") or {}
                parts.append({"type": "image_url", "image_url": {
                    "url": "data:%s;base64,%s" % (src.get("media_type", "image/jpeg"), src.get("data", ""))}})
            elif t == "tool_result":
                contenu = b.get("content")
                if isinstance(contenu, list):
                    for x in contenu:
                        if isinstance(x, dict) and x.get("type") == "image":
                            images_des_outils.append(x)
                    contenu = _g_texte_du_contenu(contenu) or "(image ou document joint ci-dessous)"
                sortie.append({"role": "tool", "tool_call_id": b.get("tool_use_id"), "content": str(contenu or "")})
        if images_des_outils:
            for x in images_des_outils:
                src = x.get("source") or {}
                parts.append({"type": "image_url", "image_url": {
                    "url": "data:%s;base64,%s" % (src.get("media_type", "image/jpeg"), src.get("data", ""))}})
        if parts:
            sortie.append({"role": "user", "content": parts})
    return sortie


def _g_outils(tools):
    sortie = []
    for o in tools or []:
        if not isinstance(o, dict) or o.get("type") or not o.get("name"):
            continue                   # les outils "serveur" d'Anthropic n'existent pas chez Google
        sortie.append({"type": "function", "function": {
            "name": o["name"], "description": str(o.get("description") or ""),
            "parameters": o.get("input_schema") or {"type": "object", "properties": {}}}})
    return sortie


class _GMessages:
    def __init__(self, parent):
        self.p = parent

    def create(self, max_tokens=8000, model=None, system=None, messages=None, tools=None,
               thinking=None, extra_body=None, timeout=None, **_ignore):
        corps = {"model": model or modele_gemini(), "messages": _g_messages(system, messages),
                 "max_tokens": int(max_tokens or 8000)}
        outils = _g_outils(tools)
        if outils:
            corps["tools"] = outils
        corps["reasoning_effort"] = "low" if (thinking or {}).get("type") == "disabled" else "medium"
        req = urllib.request.Request(GEMINI_URL, data=json.dumps(corps).encode("utf-8"), method="POST",
                                     headers={"Content-Type": "application/json",
                                              "Authorization": "Bearer " + self.p.cle})
        delai = timeout or self.p.timeout          # None = pas de limite a nous (comme avant)
        essais = 1 + int(self.p.max_retries or 0)
        derniere = None
        for _k in range(essais):
            try:
                with urllib.request.urlopen(req, timeout=delai) as r:
                    d = json.loads(r.read().decode("utf-8"))
                break
            except urllib.error.HTTPError as ex:
                try:
                    detail = ex.read().decode("utf-8", "replace")[:400]
                except Exception:
                    detail = ""
                derniere = RuntimeError("Gemini a refuse (%s) : %s" % (ex.code, detail))
                if ex.code < 500 and ex.code != 429:
                    raise derniere
            except Exception as ex:
                derniere = ex
        else:
            raise derniere or RuntimeError("Gemini ne repond pas")
        choix = (d.get("choices") or [{}])[0]
        msg = choix.get("message") or {}
        contenu = []
        if msg.get("content"):
            contenu.append(_GBloc(type="text", text=str(msg["content"])))
        for a in msg.get("tool_calls") or []:
            try:
                args = json.loads((a.get("function") or {}).get("arguments") or "{}")
            except Exception:
                args = {}
            contenu.append(_GBloc(type="tool_use", id=a.get("id") or ("g%d" % len(contenu)),
                                  name=(a.get("function") or {}).get("name") or "", input=args, _brut=a))
        fin = choix.get("finish_reason") or "stop"
        stop = {"tool_calls": "tool_use", "length": "max_tokens", "content_filter": "refusal"}.get(fin, "end_turn")
        if msg.get("tool_calls"):
            stop = "tool_use"
        u = d.get("usage") or {}
        usage = _GBloc(input_tokens=int(u.get("prompt_tokens") or 0),
                       output_tokens=int(u.get("completion_tokens") or 0),
                       cache_read_input_tokens=0, cache_creation_input_tokens=0,
                       cache_creation=None, server_tool_use=None)
        return _GReponse(contenu, stop, usage)

    def stream(self, max_tokens=8000, **kw):
        reponse = self.create(max_tokens=max_tokens, **kw)

        class _Flux:
            def __enter__(s):
                return s

            def __exit__(s, *a):
                return False

            @property
            def text_stream(s):
                for b in reponse.content:
                    if getattr(b, "type", "") == "text":
                        yield b.text

            def get_final_message(s):
                return reponse
        return _Flux()


class ClientGemini:
    def __init__(self, cle, timeout=None, max_retries=2):
        self.cle, self.timeout, self.max_retries = cle, timeout, max_retries
        self.messages = _GMessages(self)

    def with_options(self, timeout=None, max_retries=None, **_ignore):
        return ClientGemini(self.cle, timeout if timeout is not None else self.timeout,
                            max_retries if max_retries is not None else self.max_retries)


def client_de(cerveau):
    """Rend le client a utiliser pour ce cerveau. Claude -> le client d'avant (inchange)."""
    if fournisseur_de(cerveau) == "gemini":            # V180
        cle = lire_cle_gemini()
        return ClientGemini(cle) if cle else None
    if fournisseur_de(cerveau) != "deepseek":
        return client
    cle = lire_cle_deepseek()
    if not cle:
        return None
    if _client_ds["cle"] != cle:
        _client_ds["client"] = _client_deepseek()
        _client_ds["cle"] = cle
    return _client_ds["client"]


def definir_cle_deepseek(nouvelle):
    """Enregistre la cle DeepSeek dans ~/Luciana/cle_deepseek.txt."""
    nouvelle = (nouvelle or "").strip()
    if not nouvelle.startswith("sk-"):
        return False, "Cette cle ne ressemble pas a une cle API (elle commence par sk-)."
    try:
        with open(FICHIER_CLE_DEEPSEEK, "w", encoding="utf-8") as f:
            f.write(nouvelle)
        _client_ds["cle"] = None  # on refabriquera le client avec la nouvelle cle
        _client_ds["client"] = None
        return True, ""
    except Exception as e:
        return False, str(e)


def definir_cle(nouvelle):
    """Enregistre la cle collee depuis la fenetre de Luciana.
    v75 : une cle Claude commence par 'sk-ant-' -> elle va dans cle_api.txt (comme avant).
    Une AUTRE cle en 'sk-' est prise pour une cle DeepSeek -> elle va dans cle_deepseek.txt.
    Rend (ok, erreur, ou_est_allee_la_cle)."""
    global CLE, client
    nouvelle = (nouvelle or "").strip()
    if nouvelle.startswith("AIza"):                 # V180 : une cle Gemini
        ok, err = definir_cle_gemini(nouvelle)
        return ok, err, ("gemini" if ok else "")
    if not nouvelle.startswith("sk-"):
        return False, "Cette cle ne ressemble pas a une cle API (celle de Claude commence par sk-ant-, celle de DeepSeek par sk-).", ""
    if not nouvelle.startswith("sk-ant-"):
        ok, err = definir_cle_deepseek(nouvelle)
        return ok, err, ("deepseek" if ok else "")
    try:
        with open(FICHIER_CLE, "w", encoding="utf-8") as f:
            f.write(nouvelle)
        CLE = nouvelle
        client = anthropic.Anthropic(api_key=nouvelle)
        return True, "", "claude"
    except Exception as e:
        return False, str(e), ""


# ---------- v76 : LA CLE, MONTREE SANS ETRE MONTREE, ET VERIFIEE POUR DE VRAI ----------
def cle_masquee(cle=None):
    """La cle telle qu'on l'affiche a l'ecran : sk-ant-••••••••3f2a. Le milieu ne sort jamais."""
    c = (cle if cle is not None else (lire_cle() or "")).strip()
    if not c:
        return ""
    if len(c) <= 12:
        return "•" * 8
    return c[:7] + "•" * 8 + c[-4:]


# Le modele le MOINS CHER de la table des cerveaux (c'est lui qui sert au test de la cle).
def _modele_le_moins_cher():
    claude = [(v["prix"][0] + v["prix"][1], v["modele"]) for v in CERVEAUX.values()
              if v.get("fournisseur") == "anthropic"]
    return min(claude)[1] if claude else "claude-haiku-4-5"


def _cle_en_clair(ex):
    """Traduit n'importe quelle panne de l'API en une phrase que Fred comprend. JAMAIS un code
    technique : il n'est pas technicien, et un code ne lui dit rien."""
    t = (str(ex) + " " + type(ex).__name__).lower()
    if any(m in t for m in ("authentication", "invalid x-api-key", "invalid api key", "401",
                            "unauthorized", "permission_error", "403")):
        return ("Ta cle est REFUSEE par le service : elle est fausse, expiree, ou elle a ete revoquee. "
                "Il faut en recoller une neuve (bouton 'Remplacer la cle').")
    if any(m in t for m in ("credit balance", "insufficient", "402", "billing", "payment",
                            "quota", "exceeded your")):
        return ("Ta cle est bonne, mais il n'y a PLUS D'ARGENT sur le compte (ou le plafond est "
                "atteint). Recharge le compte et je repars aussitot.")
    if any(m in t for m in ("rate limit", "429", "too many")):
        return ("Ta cle marche. Le service te demande juste d'attendre un petit moment : trop de "
                "demandes d'un coup. Reessaie dans une minute.")
    if any(m in t for m in ("connection", "timeout", "timed out", "ssl", "getaddrinfo", "network",
                            "unreachable", "dns", "proxy", "overloaded", "500", "502", "503", "504")):
        return ("Je N'AI PAS PU JOINDRE le service : ca vient de la connexion internet ou du service "
                "lui-meme, pas de ta cle. Reessaie dans un moment.")
    return ("Je n'ai pas pu verifier ta cle : le service a repondu quelque chose que je ne sais pas "
            "t'expliquer simplement. Reessaie dans un instant, et si ca recommence, remplace la cle.")


def verifier_cle_api():
    """Un VRAI petit appel : 16 jetons au maximum, sur le modele le moins cher. Rend une phrase
    en francais clair, jamais un code technique."""
    c = lire_cle()
    if not c:
        return {"ok": False, "msg": "Il n'y a aucune cle Claude enregistree pour l'instant. Colle-la ici."}
    modele = _modele_le_moins_cher()
    try:
        cli = anthropic.Anthropic(api_key=c)
        cli.messages.create(model=modele, max_tokens=16,
                            messages=[{"role": "user", "content": "Reponds juste : ok"}])
        return {"ok": True, "msg": "Ta cle MARCHE : le service a repondu. (Test minuscule : 16 jetons "
                                   "au maximum, sur le modele le moins cher, ca ne coute presque rien.)"}
    except Exception as ex:
        return {"ok": False, "msg": _cle_en_clair(ex)}


