def _signature_reglages():
    r = _charger_json_sur(FICHIER_SIGNATURE, {})
    r = r if isinstance(r, dict) else {}
    r.setdefault("active", True)
    r.setdefault("proprietaire", PROPRIETAIRE_DEFAUT)
