def _prenom_seul(x):
    """Le PRENOM, jamais le nom de famille : on garde le premier mot, et 'Frederic' redevient 'Fred'."""
    p = str(x or "").strip().split(",")[0].strip()
    p = p.split()[0] if p.split() else ""
    bas = _sans_accents(p)
    if bas.startswith("freder") or bas.startswith("fredh"):
        return "Fred"
    return p


def _est_financier(destinataire, r=None):
    r = r or _signature_reglages()
    t = _sans_accents("%s" % (destinataire or ""))
    if not t:
        return False
    mots = list(_FINANCIERS) + [_sans_accents(str(x)) for x in (r.get("financiers_en_plus") or []) if str(x).strip()]
    return any(m in t for m in mots)


def signature_pour(canal="mail", au_nom_du_proprietaire=False, destinataire="", financier=None, r=None):
    """Rend le TEXTE EXACT de la signature a coller, ou '' s'il n'en faut pas. Zero token."""
    r = r or _signature_reglages()
    if not r.get("active"):
        return ""
    prenom = _prenom_seul(r.get("proprietaire"))
    societe = str(r.get("societe") or "").strip()
    if financier is None:
        financier = _est_financier(destinataire, r)
    if financier:
        # Banque / organisme financier : aucune mention d'IA. Sans prenom connu : rien du tout.
        return prenom or ""
    if au_nom_du_proprietaire:
        sur_mesure = str(r.get("texte_pour_le_proprietaire") or "").strip()
        if sur_mesure:
            return sur_mesure
        if prenom:
            return "%s, copilote IA, pour %s" % (NOM_ASSISTANTE, prenom)
        return "%s, copilote IA" % NOM_ASSISTANTE
    sur_mesure = str(r.get("texte_ia") or "").strip()
    if sur_mesure:
        return sur_mesure
    bouts = ["%s, copilote IA" % NOM_ASSISTANTE]
    if prenom:
        bouts[0] += " de %s" % prenom
    if societe:
        bouts.append(societe)
    return ", ".join(bouts)


def signer_message(texte, canal="mail", au_nom_du_proprietaire=False, destinataire="", financier=None):
    """Ajoute la signature SI elle n'y est pas deja. Rend (texte_signe, signature_ajoutee_ou_vide).
    Aucun appel a un cerveau : 0 token, 0 centime."""
    t = str(texte or "").rstrip()
    sig = signature_pour(canal, au_nom_du_proprietaire, destinataire, financier)
    if not sig or not t:
        return t, ""
    fin = _sans_accents(t[-400:])
    if _sans_accents(sig) in fin:
        return t, ""                                   # elle l'a deja ecrite : on ne double pas
    if "copilote ia" in fin and not _est_financier(destinataire):
        return t, ""                                   # une signature IA est deja la, sous une autre forme
    return t + "\n\n— " + sig, sig


def outil_signature(e):
    """La signature automatique : la voir, la changer, l'enlever, l'eteindre, la rallumer.
    Fred le dit en un message, et c'est fait."""
    action = _sans_accents(str(e.get("action") or "etat")).strip()
    r = _signature_reglages()
    if action.startswith("etat") or action.startswith("voir"):
        prenom = _prenom_seul(r.get("proprietaire"))
        return ("Signature automatique : %s. Proprietaire : %s. Societe : %s.\n"
                "- mails et WhatsApp : \"%s\"\n- message au nom de %s : \"%s\"\n"
                "- banque ou organisme financier : \"%s\" (aucune mention d'IA)\n"
                "C'est le programme qui l'ajoute tout seul, sans que tu y penses et sans rien couter "
                "en jetons. Fred peut la changer, l'enlever ou l'eteindre en un message." % (
                    "ACTIVE" if r.get("active") else "ETEINTE",
                    prenom or "pas encore connu (signature generique)", r.get("societe") or "(aucune)",
                    signature_pour("mail", False, "", False, r) or "(aucune)",
                    prenom or "son proprietaire",
                    signature_pour("mail", True, "", False, r) or "(aucune)",
                    signature_pour("mail", False, "", True, r) or "(rien : aucun prenom connu)"))
    if action.startswith("desactiv") or action.startswith("eteind") or action.startswith("arret"):
        r["active"] = False
        _sauver_signature_reglages(r)
        return "Signature automatique ETEINTE. Plus aucune signature ne sera ajoutee tant que Fred ne la rallume pas."
    if action.startswith("activ") or action.startswith("rallum"):
        r["active"] = True
        _sauver_signature_reglages(r)
        return "Signature automatique RALLUMEE : \"%s\"." % signature_pour("mail", False, "", False, r)
    if action.startswith("retir") or action.startswith("enlev") or action.startswith("suppr"):
        r["texte_ia"] = ""
        r["texte_pour_le_proprietaire"] = ""
        r["active"] = False
        _sauver_signature_reglages(r)
        return ("Signature RETIREE (textes effaces et signature eteinte). Dis-moi 'remets ta signature' "
                "pour revenir a celle d'origine.")
    if action.startswith("regl") or action.startswith("chang") or action.startswith("modif"):
        change = []
        if e.get("texte") is not None:
            r["texte_ia"] = str(e.get("texte") or "").strip()
            change.append("texte des mails et de WhatsApp")
        if e.get("texte_au_nom_du_proprietaire") is not None:
            r["texte_pour_le_proprietaire"] = str(e.get("texte_au_nom_du_proprietaire") or "").strip()
            change.append("texte des messages ecrits en son nom")
        if e.get("proprietaire"):
            r["proprietaire"] = _prenom_seul(e.get("proprietaire"))
            change.append("prenom du proprietaire")
        if e.get("societe") is not None:
            r["societe"] = str(e.get("societe") or "").strip()
            change.append("societe")
        for x in e.get("financiers_en_plus") or []:
            x = str(x).strip().lower()
            if x and x not in r["financiers_en_plus"]:
                r["financiers_en_plus"].append(x)
                change.append("organisme financier '%s'" % x)
        if not change:
            return ("Dis-moi quoi changer : 'texte' (mails/WhatsApp), 'texte_au_nom_du_proprietaire', "
                    "'proprietaire' (le prenom), 'societe'.")
        r["active"] = True
        _sauver_signature_reglages(r)
        return "C'est change (%s). Maintenant : \"%s\"." % (", ".join(change),
                                                            signature_pour("mail", False, "", False, r))
    return "Action inconnue '%s'. Actions : etat, regler, retirer, desactiver, activer." % action


# ---------- COMPTA (un petit livre de comptes, sur ton PC) ----------
def _charger_comptes():
    return _charger_json_sur(FICHIER_COMPTES, [])


def _sauver_comptes(ops):
    # Ecriture sure (fichier temporaire puis renommage) : une coupure ne peut pas abimer les comptes.
    _garder_precedent(FICHIER_COMPTES)
    tmp = FICHIER_COMPTES + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(ops, f, ensure_ascii=False, indent=2)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, FICHIER_COMPTES)


def outil_compta_ajouter(e):
    libelle = (e.get("libelle") or "").strip()
    try:
        montant = float(str(e.get("montant")).replace(",", "."))
    except (TypeError, ValueError):
        return "Donne-moi un montant en chiffres, s'il te plait."
    genre = (e.get("type") or "").strip().lower()
    if genre not in ("revenu", "depense", "dépense"):
        genre = "revenu" if montant >= 0 else "depense"
    genre = "depense" if genre.startswith("dep") else "revenu"
    date = (e.get("date") or time.strftime("%Y-%m-%d")).strip()
    ops = _charger_comptes()
    ops.append({"date": date, "libelle": libelle, "montant": abs(montant), "type": genre})
    _sauver_comptes(ops)
    return "Note : %s de %.2f (%s) le %s. C'est enregistre." % (genre, abs(montant), libelle or "sans libelle", date)


def outil_compta_bilan(e):
    mois = (e.get("mois") or "").strip()  # format AAAA-MM optionnel
    ops = _charger_comptes()
    if mois:
        ops = [o for o in ops if str(o.get("date", "")).startswith(mois)]
    revenus = sum(o["montant"] for o in ops if o.get("type") == "revenu")
    depenses = sum(o["montant"] for o in ops if o.get("type") == "depense")
    quand = ("pour " + mois) if mois else "en tout"
    return "Bilan %s : %.2f de revenus, %.2f de depenses, solde %.2f (sur %d operations)." % (
        quand, revenus, depenses, revenus - depenses, len(ops))


def outil_compta_liste(e):
    n = int(e.get("combien") or 20)
    ops = _charger_comptes()[-n:]
    if not ops:
        return "Ton livre de comptes est vide pour l'instant."
    lignes = ["Dernieres operations :"]
    for o in ops:
        signe = "+" if o.get("type") == "revenu" else "-"
        lignes.append("%s  %s%.2f  %s" % (o.get("date", ""), signe, o.get("montant", 0), o.get("libelle", "")))
    return "\n".join(lignes)


