def _executer_outil(nom, entree):
    nom = ANCIENS_NOMS_OUTILS.get(nom, nom)      # v80 : un ancien nom d'outil marche encore
    fn = OUTILS.get(nom)
    if not fn:
        return "Outil inconnu : %s" % nom
    try:
        if touche_le_code_de_luciana(nom, entree) and not code_de_luciana_autorise():
            return V180_REFUS_VERROU
    except Exception:
        return V180_REFUS_VERROU             # dans le doute, le verrou reste ferme
    try:
        # v146 : LE VERROU DE SURVEILLANCE ("la nounou"). C'est ICI, et nulle part ailleurs, que
        # le programme sait qu'une ecriture vient d'une DECISION de Luciana, et pas d'une boucle
        # de fond. Si l'interrupteur est EN VEILLE ou ETEINT, ce 'with' ne change rien du tout.
        with nounou_pendant_un_outil(nom):
            sortie = fn(entree or {})
    except DemandeEnAttenteDeFred as attente:
        # v146 : RIEN N'A ETE ECRIT. La demande est dans la file, elle attend le clic de Fred.
        # On le dit a Luciana en clair : ce n'est PAS une panne, et ce n'est PAS "c'est fait".
        return attente.phrase_pour_luciana
    except ArretDemandeParFred:
        # V176 : meme raison qu'ailleurs. Sans ces deux lignes, le 'except Exception' juste en
        # dessous transformerait l'arret de Fred en "Erreur pendant ..." : l'arret serait
        # avale et le tour continuerait. On le laisse remonter tel quel jusqu'a repondre().
        raise
    except Exception as ex:
        return "Erreur pendant %s : %s" % (nom, ex)
    if nom in _OUTILS_CONTENU_EXTERIEUR and isinstance(sortie, str) and "[CONTENU LU SUR" not in sortie:
        sortie = _encadrer_web(sortie, "l'outil %s" % nom)
    return sortie


