def _qui_parle(m):
    return "Fred" if (m or {}).get("role") == "user" else "Luciana"


def _quand_parle(m):
    """'22h31' tire de la date du message, ou '' si le message n'a pas de date."""
    d = str((m or {}).get("date") or "")
    mm = re.search(r"(\d{2}):(\d{2})", d)
    return ("%sh%s" % (mm.group(1), mm.group(2))) if mm else ""


def _texte_entier_du_message(m):
    """Le texte du message tel qu'il est dans la memoire, PLUS son journal d'outils s'il en a un.
    MOT POUR MOT : aucun resume, aucune compression. Le journal est garde parce que, une fois le
    passage range, il ne repart plus au cerveau : l'oublier serait perdre ce qu'elle a fait."""
    c = (m or {}).get("content")
    texte = c if isinstance(c, str) else str(c)
    actions = (m or {}).get("actions")
    if actions:
        texte += ("\n    [outils vraiment utilises a ce tour -> "
                  + " | ".join(str(a) for a in actions) + "]")
    return texte


# =====================================================================
#  3) PYTHON RANGE (et cree les tiroirs)
