RANGEMENT_PAR_PYTHON = False


def _noter_sortis_de_la_fenetre(hist, debut, coupe, paquet):
    """v128 : note dans journee_rangee.json que les messages [debut, coupe) sortent de la fenetre
    (ils sont dans le grand tiroir, qui indexe TOUTE la memoire). Appele SOUS _verrou_tour.
    Ecriture sure (temporaire + renommage). Rend (numeros ecrits, probleme)."""
    carnet = dict(charger_journee_rangee())
    carnet["messages"] = list(carnet.get("messages") or [])
    ecrits = []
    for n in range(debut, coupe):
        m = hist[n]
        ecrits.append({"numero": n, "date": str(m.get("date") or ""),
                       "heure": time.strftime("%Hh%M"), "rayon": "grand-tiroir", "dossier": "",
                       "fiche": "", "ligne": "", "par": "python"})
    if not ecrits:
        return [], ""
    carnet["messages"].extend(ecrits)
    carnet["dernier"] = max([-1] + [int(x.get("numero", -1)) for x in carnet["messages"]])
    carnet["dernier_rangement"] = {"quand": time.strftime("%Y-%m-%d %H:%M"), "messages": len(ecrits),
                                   "caracteres": paquet, "tiroirs": ["grand tiroir (memoire par le sens)"],
                                   "crees": []}
    try:
        _sauver_journee_rangee(carnet)
    except Exception as ex:
        probleme = "je n'ai pas pu ecrire journee_rangee.json : %s" % str(ex)[:200]
        _journal_rangement({"resultat": "carnet non ecrit", "raison": probleme, "cerveau": "python"})
        return [], probleme
    return ecrits, ""


def _v182_archiviste_range(hist, debut, coupe):
    """V182 : L'ARCHIVISTE DE LA MEMOIRE 2 RANGE LES MESSAGES [debut, coupe) -- ceux qui sortent
    de la fenetre au seuil de Fred. Le MEME code que « Ranger TOUTE ma memoire »
    (biblio2_reprise.reprendre, le meme DeepSeek reflechi), mais seulement sur ces messages.
    Dans la foulee, il range aussi ce qui est NOUVEAU dans souvenirs.json et dans les souvenirs de
    l'ancienne bibliotheque (par ex. une chose en cours devenue « faite », que le programme y
    classe) : ce qui est deja range n'est jamais range deux fois (les reperes).
    Rend (True, "") si c'est range (ou si la memoire 2 n'est pas branchee : rien a faire), ou
    (False, raison) en cas de panne -- et alors l'appelant ne marque rien. Ne leve jamais."""
    if not biblio2_branche():
        return True, ""
    try:
        import biblio2_reprise as _rep
        import biblio2_archiviste as _a2
        _rep.print = lambda *a, **k: None
        souvenirs, precedents = [], []
        for n in range(0, coupe):
            m = hist[n] if n < len(hist) else None
            if not isinstance(m, dict):
                continue
            texte = str(m.get("content") or "").strip()
            qui = "Fred" if m.get("role") == "user" else "Luciana"
            utilisable = len(texte) >= _rep.TEXTE_TROP_COURT and not texte.startswith("[")
            if n >= debut and utilisable:
                souvenirs.append({"texte": texte, "source": "conversation",
                                  "date": str(m.get("date") or "")[:10], "role": m.get("role") or "",
                                  "contexte": list(precedents),
                                  "repere": _a2.repere_de("conversation", texte)})
            if texte and not texte.startswith("["):
                precedents = (precedents + ["%s : %s" % (qui, texte)])[-_rep.CONTEXTE_MESSAGES:]

        def _juge(souvenir, arbre):
            j = _a2.juger_avec_reessais(_rep.juger_deepseek, souvenir, arbre)   # 17/10 : reessaie
            if isinstance(j, dict) and j.get("_panne"):
                raise RuntimeError(_a2.phrase_de_la_panne(j["_panne"]))
            return j

        def _les_sources():
            tout, soucis = list(souvenirs), []
            # 18/10/2026 (Fred) : la bibliotheque 1 est DEBRANCHEE. L'archiviste lit la liste
            # d'attente (ce qui a ete confie et pas encore range), plus jamais la bibliotheque 1.
            for lire in (_rep._depuis_souvenirs_json, _rep._depuis_la_liste_d_attente):
                try:
                    lot, souci = lire()
                    tout += lot
                    if souci:
                        soucis.append(souci)
                except Exception as ex:
                    soucis.append(str(ex)[:120])
            return tout, soucis
        _rep.reprendre(_juge, sources=_les_sources)
        _rep.sortir_de_l_attente_ce_qui_est_range()       # 18/10/2026
        _v191_plan_dans_la_boite()      # V191 : le plan entier, dans la boite a outils de Luciana
        _trace_biblio2({"archiviste_au_seuil": "ok", "messages": len(souvenirs), "v182": True})
        return True, ""
    except Exception as ex:
        _trace_biblio2({"archiviste_au_seuil": "panne", "pourquoi": str(ex)[:200], "v182": True})
        return False, "l'archiviste de la memoire 2 n'a pas pu ranger (%s) : rien n'est marque, il reessaiera" % str(ex)[:160]


_V195_ATTENTE_EN_COURS = threading.Lock()


def confier_a_l_archiviste(texte, source, quand=""):
    """18/10/2026 (Fred) : TOUT CE QUI ENTRE VA A L'ARCHIVISTE, DANS LA BIBLIOTHEQUE EN SERVICE.
    Le morceau est mis dans la liste d'attente, puis un fil a part demande a l'archiviste de le
    ranger tout de suite. S'il ne peut pas (internet coupe, bibliotheque occupee, rangement
    suspendu par le bouton), le morceau reste dans la liste et l'archiviste du jour le reprend a son
    passage suivant. Rend (True, phrase vraie) ou (False, raison). Ne leve jamais."""
    try:
        import biblio2_reprise as _rep
        r = _rep.mettre_en_attente(texte, source, str(quand or "")[:10])
        if not r:
            return False, "le morceau n'a pas pu etre confie a l'archiviste (liste d'attente illisible)"
    except Exception as ex:
        return False, str(ex)[:200]

    def _travail():
        if not _V195_ATTENTE_EN_COURS.acquire(blocking=False):
            return                      # un autre fil s'en occupe deja : il prendra aussi celui-ci
        try:
            import biblio2_reprise as _rep
            import biblio2_archiviste as _a2
            _rep.print = lambda *a, **k: None
            brut = getattr(_rep, "juger_par_l_ia", None) or getattr(_rep, "juger_deepseek")

            def _juge(souvenir, arbre):
                j = _a2.juger_avec_reessais(brut, souvenir, arbre)
                if isinstance(j, dict) and j.get("_panne"):
                    raise RuntimeError(_a2.phrase_de_la_panne(j["_panne"]))
                return j
            for _essai in range(3):
                if _RANGEMENT_ETAT.get("suspendu") or not biblio2_branche():
                    return                  # le bouton Suspendre : rien ne part, tout attend
                try:
                    _rep.reprendre(_juge, sources=_rep._depuis_la_liste_d_attente)
                    _rep.sortir_de_l_attente_ce_qui_est_range()
                    _v191_plan_dans_la_boite()
                    _trace_biblio2({"confie_a_l_archiviste": "range"})
                    return
                except Exception as ex:
                    _trace_biblio2({"confie_a_l_archiviste": "attend", "pourquoi": str(ex)[:200]})
                    if "occupee" not in str(ex):
                        return              # panne : il attend dans la liste, l'archiviste du jour le reprendra
                    time.sleep(60)          # la bibliotheque est occupee : on reessaie un peu plus tard
        except Exception:
            pass
        finally:
            _V195_ATTENTE_EN_COURS.release()
    try:
        threading.Thread(target=_travail, name="confie-a-l-archiviste", daemon=True).start()
    except Exception:
        pass
    return True, ("confie a l'archiviste : il le range dans la bibliotheque en service (s'il ne peut "
                  "pas tout de suite, le morceau attend dans sa liste et il le reprend a son passage suivant)")


def ranger_la_journee():
    """LE RANGEMENT. Tourne dans un fil a part.

    CORRECTION DU 06/10/2026 -- LE VERROU. AVANT : ce fil prenait _verrou_tour et le GARDAIT
    pendant tout son travail, appels au cerveau compris. Resultat vu par Fred le 06/10 vers 01h48 :
    "ca bloque tout le systeme", jusqu'a 40 minutes, et ses messages de 01h40 et 01h48 n'ont eu
    AUCUNE reponse (appel au cerveau en timeout). L'intention etait de ne jamais croiser un
    rangement et un tour de conversation ; l'effet etait que c'etait la CONVERSATION qui attendait.
    MAINTENANT : le verrou n'est pris QUE le temps de toucher a la memoire partagee --
      (1) lire la memoire + la zone a ranger (quelques millisecondes) ;
      (2) ecrire les fiches de la bibliotheque puis journee_rangee.json (voir _ecrire_le_paquet).
    L'APPEL AU CERVEAU, lui, se fait SANS le verrou : le rangement peut penser pendant que Fred
    parle, et Luciana repond a chaque message sans attendre.
    CE QUI N'EST PAS CASSE POUR AUTANT : deux ecritures en meme temps dans la memoire partagee
    restent impossibles. Mieux, comme repondre() garde _verrou_tour pendant TOUT son tour, une
    ecriture du rangement ne peut toujours pas tomber AU MILIEU d'un tour de conversation : elle
    attend sagement la fin du tour. L'ordre des messages est donc garde, exactement comme avant.

    luciana_memoire.json n'est JAMAIS ouvert en ecriture ici. Ne leve jamais.
    Rend un petit compte rendu, pour le journal et pour les controles."""
    compte = {"appels": 0, "messages": 0, "caracteres": 0, "tiroirs": [], "crees": [],
              "cout": 0.0, "probleme": ""}
    if not RANGEMENT_JOURNEE_ACTIF:
        compte["probleme"] = "le rangement de la journee est eteint (reglage_rangement_journee.json)"
        return compte
    cerveau = "python (v128)"
    while compte["appels"] < RANGEMENT_APPELS_MAX:
        # LE BOUTON DE FRED, LU ICI AUSSI (06/10/2026) : un cycle deja en route enchaine jusqu'a 6
        # paquets, qui durent des minutes chacun. Sans cette ligne, cliquer "Suspendre" pendant un
        # cycle ne l'arretait pas : il continuait pendant toute la reunion. Le paquet EN COURS, lui,
        # va au bout -- on n'abandonne jamais un rangement a moitie.
        if _RANGEMENT_ETAT.get("suspendu"):
            compte["probleme"] = "rangement suspendu a la main par Fred (bouton Suspendre)"
            break
        # ---- VERROU PRIS, JUSTE LE TEMPS DE LIRE LA MEMOIRE PARTAGEE (quelques millisecondes) ----
        # La memoire ET le carnet de rangement sont lus ENSEMBLE, sous le meme verrou : la photo
        # est donc coherente (zone_a_ranger lit le carnet pour savoir ou commencer).
        with _verrou_tour:
            hist = charger_memoire()
            debut, fin, taille = zone_a_ranger(hist)
        # ---- VERROU RENDU. Tout ce qui suit travaille sur CETTE photo, sans bloquer personne. ----
        if debut >= fin:
            break
        # Un simple calcul sur la photo qu'on vient de prendre : rien de partage, donc hors verrou.
        tailles = [_taille_reelle_message(m) for m in hist]
        # CE QU'ON PEUT ENCORE RANGER : la journee non rangee MOINS les 10 derniers messages, qui
        # ne sont jamais ranges. C'est ce chiffre-la qu'on fait redescendre a CIBLE_APRES_RANGEMENT
        # ("il reste ~50 000 car. + les 10 derniers messages", la demande de Fred du 06/10/2026).
        rangeable = sum(tailles[debut:fin])
        # PREMIER PASSAGE : on ne range que si le SEUIL de Fred est franchi par la journee entiere.
        # PASSAGES SUIVANTS : on continue jusqu'a redescendre a la cible, "d'un bon coup" -- comme
        # ca le cache n'est recharge qu'UNE fois pour tout le rangement.
        # v162 : l'ancien test "rangeable <= CIBLE_APRES_RANGEMENT" etait FAUX : quand le fil
        # depassait le seuil de peu, ce qu'il fallait ranger etait justement plus petit que le
        # plancher -- et il ne rangeait donc rien du tout. Ce qui doit etre vrai, c'est qu'il
        # reste QUELQUE CHOSE a ranger.
        if rangeable <= 0:
            break      # rien a ranger : tout ce qui reste, c'est le fil garde
        if compte["appels"] == 0 and taille <= SEUIL_JOURNEE:
            break      # le seuil de Fred n'est pas franchi : on ne touche a rien
        paquet, coupe = 0, debut
        # v162 (demande de Fred, 11/10/2026) : ON RANGE TOUT ce qui est avant le fil garde.
        # C'est zone_a_ranger qui a calcule 'fin' de facon qu'il reste CIBLE_APRES_RANGEMENT
        # caracteres dans le fil : LE PLANCHER EST DONC GARANTI PAR CONSTRUCTION. On n'a plus a
        # le re-tester ici (c'est l'ancien test qui bloquait tout : il rendait le rangement
        # impossible des que la zone a ranger etait plus petite que le plancher).
        while (coupe < fin
               and (paquet + tailles[coupe] <= RANGEMENT_PAQUET_MAX or RANGEMENT_PAR_PYTHON)):
            paquet += tailles[coupe]
            coupe += 1
        if coupe == debut:
            # Le premier message depasse a lui seul la taille d'un paquet : on le prend quand
            # meme, sinon ce cycle ne pourrait jamais avancer (c'etait deja le cas avant).
            coupe, paquet = debut + 1, tailles[debut]
        bout = hist[debut:coupe]
        # V182 (decide avec Fred) : AU SEUIL DE 80 000 CARACTERES, LES MESSAGES QUI SORTENT DE LA
        # FENETRE PARTENT A L'ARCHIVISTE DE LA MEMOIRE 2. Il les lit EN ENTIER (avec les messages
        # juste avant pour comprendre) et les range dans la bibliotheque 2. SEULEMENT APRES, on
        # note qu'ils sortent de la fenetre (le meme carnet journee_rangee.json qu'avant : c'est
        # lui qui fait glisser la fenetre). En cas de panne (pas d'internet), on ne note RIEN :
        # les messages restent dans la fenetre et le prochain passage reessaiera.
        # (Avant la V182, ce rangement ecrivait dans l'ANCIENNE bibliotheque, celle de la memoire 1.)
        tiroirs, crees, cout, morceaux = ["memoire 2 (archiviste)"], [], 0.0, []
        ok_arch, souci_arch = _v182_archiviste_range(hist, debut, coupe)
        if not ok_arch:
            compte["probleme"] = souci_arch
            break
        with _verrou_tour:
            ecrits, souci = _noter_sortis_de_la_fenetre(hist, debut, coupe, paquet)
        if souci:
            compte["probleme"] = souci
        if not ecrits:
            break
        cerveau = "archiviste de la memoire 2"
        compte["cout"] = round(float(compte.get("cout") or 0.0) + float(cout or 0.0), 6)
        compte["messages"] += len(ecrits)
        compte["caracteres"] += paquet
        for t in tiroirs:
            if t not in compte["tiroirs"]:
                compte["tiroirs"].append(t)
        for c in crees:
            if c not in compte["crees"]:
                compte["crees"].append(c)
        compte["appels"] += 1
        _journal_rangement({"resultat": "range", "messages": len(ecrits), "caracteres": paquet,
                            "tiroirs": tiroirs, "crees": crees, "cerveau": cerveau,
                            "cout": round(cout, 4), "morceaux": len(morceaux)})
        if compte["probleme"]:
            break
    # Le bandeau d'etat doit dire la verite tout de suite apres un rangement.
    # (Lecture de la memoire partagee : verrou pris le temps de la lire, et rien de plus.)
    try:
        with _verrou_tour:
            _d, _f, t = zone_a_ranger(charger_memoire())
        _MESURE_JOURNEE.update(taille=t, quand=time.time())
    except Exception:
        pass
    return compte


def _rangement_pause_restante():
    """Combien de secondes il reste a la PAUSE qui suit trop d'echecs de suite (0 = le rangement
    peut repartir). NE DECIDE RIEN ET NE CHANGE RIEN : c'est juste le calcul, partage par le bandeau
    d'etat (qui doit dire la verite a Fred : "il reprendra tout seul dans N min") et par
    declencher_rangement_journee (qui, lui, remet le compteur a zero quand la pause est passee).
    Un seul calcul pour les deux, pour qu'ils ne puissent jamais se contredire. Ne leve jamais."""
    try:
        if int(_RANGEMENT_ETAT.get("echecs") or 0) < RANGEMENT_ECHECS_MAX:
            return 0
        depuis = float(_RANGEMENT_ETAT.get("dernier_echec") or 0.0)
        reste = RANGEMENT_PAUSE_APRES_ECHECS - (time.time() - depuis)
        return int(reste) if reste > 0 else 0
    except Exception:
        return 0


def declencher_rangement_journee(taille_journee):
    """PYTHON OBLIGE. Appele a la FIN du tour, quand la reponse de Fred est deja partie et que
    ajouter_a_la_memoire a ecrit l'echange -- ET AUSSI, depuis le 06/10/2026, par la minuterie
    _boucle_rangement_journee(), pour que le rangement avance meme quand Fred ne parle pas.
    Au-dessus de SEUIL_JOURNEE, le rangement part dans un fil a part. Ne leve jamais, ne fait
    jamais attendre Fred.

    CORRECTION DU 06/10/2026 : ce fil ne prend PLUS _verrou_tour pour tout son travail. Il le
    prenait, et le gardait pendant ses appels au cerveau (des minutes) : c'etait la CONVERSATION
    qui attendait, jusqu'a 40 minutes le 06/10. C'est maintenant ranger_la_journee() qui prend le
    verrou, tout seul, juste autour de chaque lecture / ecriture de la memoire partagee.
    L'ordre des messages reste garde : une ecriture du rangement attend la fin du tour en cours."""
    if not RANGEMENT_JOURNEE_ACTIF:
        return False
    # LE BOUTON DE FRED (06/10/2026) : suspendu = RIEN NE DEMARRE. C'est la porte d'entree de tout
    # rangement (fin de tour ET minuterie) : la fermer ici ferme tout.
    if _RANGEMENT_ETAT.get("suspendu"):
        return False
    try:
        if int(taille_journee or 0) <= SEUIL_JOURNEE:
            return False
        if _RANGEMENT_ETAT["echecs"] >= RANGEMENT_ECHECS_MAX:
            # TROIS REPONSES ILLISIBLES DE SUITE : on le dit a Fred et on ATTEND -- mais on n'attend
            # plus POUR TOUJOURS (correction du 06/10/2026). Tant que la pause court, on ne paye
            # aucun appel ; des qu'elle est passee, le compteur repart a zero et on reessaie.
            # C'est la deuxieme et DERNIERE remise a zero du programme (l'autre : un paquet qui
            # passe, dans ranger_la_journee).
            if _rangement_pause_restante() > 0:
                return False
            _RANGEMENT_ETAT["echecs"] = 0
            _RANGEMENT_ETAT["dernier_echec"] = 0.0
            _journal_rangement({"resultat": "reprise apres la pause",
                                "raison": _RANGEMENT_ETAT.get("dernier_probleme") or "",
                                "pause_secondes": RANGEMENT_PAUSE_APRES_ECHECS})
        with _verrou_rangement:
            if _RANGEMENT_ETAT["en_cours"]:
                return False
            _RANGEMENT_ETAT["en_cours"] = True
            _RANGEMENT_ETAT["depuis"] = time.time()   # pour le temoin visible du bandeau

        def travail():
            try:
                ranger_la_journee()
            except Exception:
                pass
            finally:
                with _verrou_rangement:
                    _RANGEMENT_ETAT["en_cours"] = False
                    _RANGEMENT_ETAT["depuis"] = 0.0

        threading.Thread(target=travail, name="rangement-journee", daemon=True).start()
        return True
    except Exception:
        with _verrou_rangement:
            _RANGEMENT_ETAT["en_cours"] = False
            _RANGEMENT_ETAT["depuis"] = 0.0
        return False


def _boucle_rangement_journee():
    """LA MINUTERIE DU RANGEMENT (correction du 06/10/2026). LE SEUL AJOUT : une horloge.

    LE DEFAUT REPARE : jusqu'ici, le rangement ne partait qu'a la fin d'un tour de conversation.
    Fred se tait -> plus rien ne range. Et comme un cycle ne fait au plus que RANGEMENT_APPELS_MAX
    paquets, un retard de ~45 paquets ne pouvait pas se vider : il fallait 45 messages de Fred.
    CE QUE FAIT CETTE BOUCLE, ET RIEN DE PLUS : toutes les RANGEMENT_REVEIL_SECONDES, elle mesure la
    journee et redonne la main a declencher_rangement_journee, qui decide tout le reste (seuil,
    pause apres echecs, un seul rangement a la fois). Elle ne range pas elle-meme, elle n'appelle
    JAMAIS le cerveau : le travail se fait dans le fil de fond qui existait deja
    (threading.Thread "rangement-journee"), avec la meme regle de verrou qu'avant -- _verrou_tour
    n'est pris que le temps de LIRE la memoire, jamais pendant un appel au cerveau.
    L'ENCHAINEMENT DES PAQUETS EST DONC : un cycle de RANGEMENT_APPELS_MAX paquets au plus, puis le
    fil s'arrete, puis la minuterie en relance un RANGEMENT_REVEIL_SECONDES plus tard -- jusqu'a ce
    qu'il ne reste plus rien a ranger au-dessus de la cible. C'est le plafond par cycle + la pause
    entre deux cycles demandes par Fred, et les deux chiffres sont des constantes nommees, en haut
    de la partie rangement de ce fichier.
    QUAND IL N'Y A RIEN A RANGER, CA NE COUTE RIEN : la mesure est du calcul local, zero jeton.
    Ne leve jamais : un pepin ici ne doit jamais arreter l'horloge."""
    if not RANGEMENT_JOURNEE_ACTIF:
        return
    while True:
        time.sleep(RANGEMENT_REVEIL_SECONDES)
        try:
            if _RANGEMENT_ETAT.get("suspendu"):
                continue        # BOUTON DE FRED : suspendu -> on ne mesure meme pas, zero jeton
            if _RANGEMENT_ETAT["en_cours"]:
                continue        # un cycle travaille deja : on le laisse finir, on ne mesure rien
            if _rangement_pause_restante() > 0:
                continue        # pause apres trop d'echecs : le bandeau le dit, et rien n'est paye
            # La mesure VRAIE, exactement comme la fin de ranger_la_journee() la fait deja : le
            # verrou est pris LE TEMPS DE LIRE LA MEMOIRE, et rien de plus. C'est la meme lecture
            # qu'a chaque tour de conversation, mais seulement une fois toutes les deux minutes.
            # Elle sert au declenchement ET au bandeau d'etat (le chiffre que Fred voit).
            with _verrou_tour:
                _d, _f, taille = zone_a_ranger(charger_memoire())
            _MESURE_JOURNEE.update(taille=taille, quand=time.time())
            declencher_rangement_journee(taille)
        except Exception:
            pass


def mesure_journee():
    """LE BANDEAU D'ETAT : "Journee : X car. / 200 000 - dernier rangement HHhMM (N messages ->
    tiroirs ...)". Ne lit aucune grosse memoire : le chiffre vient de la derniere mesure REELLE
    faite par repondre(), par la fin d'un rangement, ou par la minuterie _boucle_rangement_journee
    (comme mesure_memoire() pour les souvenirs et les carnets).
    Ne modifie rien et ne leve jamais."""
    if not RANGEMENT_JOURNEE_ACTIF:
        return None
    try:
        taille = int(_MESURE_JOURNEE.get("taille") or 0)
        dernier = (charger_journee_rangee().get("dernier_rangement") or {})
        bout = ""
        if dernier:
            quand = str(dernier.get("quand") or "")[11:16].replace(":", "h")
            tiroirs = ", ".join(dernier.get("tiroirs") or []) or "aucun tiroir note"
            bout = " - dernier rangement %s (%d messages -> %s)" % (
                quand or "?", int(dernier.get("messages") or 0), tiroirs)
        else:
            bout = " - aucun rangement pour l'instant"
        # LE TEMOIN VISIBLE (06/10/2026) : quand le rangement travaille, Fred le VOIT, et il sait
        # que ca n'empeche rien -- la conversation repond pendant ce temps. Une ligne, rien de plus.
        encours = ""
        if _RANGEMENT_ETAT.get("en_cours"):
            try:
                minutes = int(max(0.0, time.time() - float(_RANGEMENT_ETAT.get("depuis") or 0.0)) // 60)
            except Exception:
                minutes = 0
            encours = (" - rangement en cours (depuis %d min, il ne te bloque pas)" % minutes)
        souci = ""
        if _RANGEMENT_ETAT["echecs"] >= RANGEMENT_ECHECS_MAX:
            # LA VERITE, ET TOUTE LA VERITE (06/10/2026) : avant, le bandeau disait "j'attends"
            # alors que le rangement etait fige POUR TOUJOURS. Maintenant il est en PAUSE, et le
            # bandeau dit quand il repart -- parce qu'il repart vraiment, tout seul.
            reste = _rangement_pause_restante()
            reprise = ("dans %d min" % ((reste + 59) // 60)) if reste > 0 else "au prochain reveil"
            # (Et on ne promet plus a Fred une action qui n'existe pas. Pendant la pause, un
            #  message de sa part ne relance RIEN : il n'y a pas d'outil "range ma journee" dans
            #  ce programme. Le seul vrai levier tout de suite, c'est une relance -- le compteur
            #  d'echecs n'est qu'en memoire, il repart donc a zero au demarrage. Changer de
            #  cerveau, lui, sert pour l'essai SUIVANT : ranger_la_journee relit le cerveau
            #  choisi dans le menu a chaque rangement.)
            souci = (" - rangement EN PAUSE apres %d echecs de suite (%s). RIEN n'est perdu (ma "
                     "memoire est entiere) et IL REPRENDRA TOUT SEUL %s. CE QU'IL FAUT FAIRE : "
                     "rien, il repart sans toi. Si tu ne veux pas attendre, relance-moi. Et si ca "
                     "rate encore, change de cerveau dans le menu."
                     % (_RANGEMENT_ETAT["echecs"],
                        _RANGEMENT_ETAT["dernier_probleme"] or "raison inconnue", reprise))
        return {"ligne": "Fil garde : %s car. / %s (au-dela, je range jusqu'a %s)%s%s%s" % (
                    _en_car(taille), _en_car(SEUIL_JOURNEE), _en_car(CIBLE_APRES_RANGEMENT),
                    bout, encours, souci),
                "a_trier": bool(souci), "taille": taille, "seuil": SEUIL_JOURNEE,
                "echecs": _RANGEMENT_ETAT["echecs"], "en_cours": _RANGEMENT_ETAT["en_cours"],
                # LE BOUTON DE FRED (06/10/2026) : l'etat vrai de la suspension, pour que la page le
                # DISE et que le bouton montre la bonne etiquette. Deja branche dans /etat_travaux,
                # deja rafraichi toutes les 8 s : il n'y a rien d'autre a cabler.
                "suspendu": bool(_RANGEMENT_ETAT.get("suspendu"))}
    except Exception:
        return None


# =====================================================================
#  BIBLIO2 : LE BIBLIOTHECAIRE (memoire a facettes), DERRIERE UN INTERRUPTEUR + FILET.
#  OFF par defaut : si ~/Luciana/bibliotheque2/BRANCHE.txt n'existe pas, ou si l'arbre est
#  vide, ou au moindre pepin -> on rend None et _repondre_tour garde EXACTEMENT son
#  comportement d'aujourd'hui. Luciana ne peut donc pas casser.
#  ON (le fichier existe) : l'IA lit la demande, le Python descend l'arbre range par
#  l'archiviste, et on sert a Luciana le bloc de memoire choisi. Luciana ne cherche pas.
# =====================================================================
_BIBLIO2_DOSSIER = os.path.join(DOSSIER, "bibliotheque2")
_BIBLIO2_MARQUEUR = os.path.join(_BIBLIO2_DOSSIER, "BRANCHE.txt")
_BIBLIO2_ARBRE = os.path.join(_BIBLIO2_DOSSIER, "arbre.json")
_BIBLIO2_CURSEUR = os.path.join(_BIBLIO2_DOSSIER, "curseur.txt")
_BIBLIO2_PLAN = os.path.join(_BIBLIO2_DOSSIER, "plan.json")        # le plan a 4 niveaux
BIBLIO2_CURSEUR_SECOURS = 0.35  # ne sert que si le reglage ET curseur.txt manquent tous les deux


def _biblio2_reglages():
    """LE TABLEAU DE BORD COMMUN (point 2 du chantier du 11/10/2026) : tous les seuils de la
    memoire 2 sont dans reglage_biblio2.json, relu a chaque message. Rend None si le fichier
    de reglage n'est pas la -- l'appelant reprend alors ses valeurs de secours. Ne leve jamais."""
    try:
        import biblio2_reglages as _r
        return _r
    except Exception:
        return None


def biblio2_branche():
    """L'interrupteur, lu A CHAQUE message (Fred branche/debranche sans redemarrer)."""
    try:
        return os.path.exists(_BIBLIO2_MARQUEUR)
    except Exception:
        return False


def _biblio2_curseur():
    """LE CURSEUR DE PERTINENCE, lu A CHAQUE message (Fred le regle sans redemarrer, comme
    l'interrupteur). Un simple nombre dans ~/Luciana/bibliotheque2/curseur.txt (ex. 0.35).

    POINT 2 DU CHANTIER DU 11/10/2026 : plus rien en dur. Le maitre reste curseur.txt (le
    bouton « Regler le curseur memoire »). S'il manque, on prend la valeur du fichier de
    reglage commun, et seulement en tout dernier recours la valeur de secours. On ne remonte
    JAMAIS de soi-meme le curseur choisi par Fred. Borne a [0, 1]. Ne leve JAMAIS."""
    try:
        with open(_BIBLIO2_CURSEUR, encoding="utf-8-sig") as f:
            v = float(f.read().strip().replace(",", "."))
        return min(1.0, max(0.0, v))
    except Exception:
        pass
    r = _biblio2_reglages()
    if r is not None:
        try:
            return min(1.0, max(0.0, float(r.lire()["curseur_sortie_defaut"])))
        except Exception:
            pass
    return BIBLIO2_CURSEUR_SECOURS


def _biblio2_etiquette(cat, sous, fi):
    """L'ETIQUETTE DE SENS D'UNE FICHE : une phrase COURTE et dense faite du rayon, du tiroir,
    du filtre, du sous-filtre, du resume, de l'objet, des personnes et du lieu. On passe par
    biblio2_archiviste, pour que l'archiviste et le bibliothecaire parlent EXACTEMENT de la
    meme chose ; s'il n'est pas a jour, on sait la fabriquer ici aussi (la memoire 2 continue
    donc de marcher meme si un seul des deux fichiers a ete remis a jour). Ne leve jamais."""
    try:
        import biblio2_archiviste as _a2
        return _a2.etiquette_de(cat, sous, fi)
    except Exception:
        pass
    try:
        f = fi.get("filtres") if isinstance(fi.get("filtres"), dict) else {}
        qui = f.get("qui") if isinstance(f.get("qui"), (list, tuple)) else []
        bouts = [cat, sous, fi.get("filtre"), fi.get("sous_filtre"), fi.get("resume"),
                 f.get("objet"), ", ".join(str(x) for x in qui), f.get("ou"), f.get("type")]
        vus, propres = set(), []
        for b in bouts:
            b = re.sub(r"\s+", " ", str(b or "")).strip(" .,;:-")
            if b and b.lower() not in vus:
                vus.add(b.lower())
                propres.append(b)
        return " — ".join(propres)[:600]
    except Exception:
        return ""


_BIBLIO2_ARBRE_CACHE = {"empreinte": None, "arbre": None}
# v164 : le detail du cout du dernier passage de la bibliotheque2, ecrit dans le carnet de controle.
# C'est LA MESURE qui manquait pour savoir ou passait le temps d'un tour.
_BIBLIO2_DERNIER_COUT = {}


def _biblio2_arbre():
    """v164 — L'ARBRE, LU UNE FOIS ET GARDE TANT QU'IL N'A PAS BOUGE. AVANT : arbre.json (5 879
    fiches, plusieurs megaoctets) etait relu et re-analyse A CHAQUE MESSAGE, meme quand il etait
    rigoureusement identique. MAINTENANT : on compare la taille et la date ; si rien n'a bouge, on
    reprend celui qu'on a deja. Le contenu servi est le MEME, au caractere pres. Ne leve jamais :
    au moindre doute on relit le fichier comme avant."""
    try:
        import biblio2_archiviste as _a2
    except Exception:
        return None
    sig = _signature_fichier(_BIBLIO2_ARBRE)
    try:
        if sig is not None and sig == _BIBLIO2_ARBRE_CACHE["empreinte"] and _BIBLIO2_ARBRE_CACHE["arbre"]:
            return _BIBLIO2_ARBRE_CACHE["arbre"]
    except Exception:
        pass
    try:
        arbre = _a2.arbre_charger(_BIBLIO2_ARBRE)
    except Exception:
        return None
    _BIBLIO2_ARBRE_CACHE.update(empreinte=sig, arbre=arbre)
    return arbre


# v164 : les bouts deja prepares, pour l'arbre tel qu'il est en ce moment. La cle est l'identite
# de la fiche DANS CET ARBRE-LA ; des que l'arbre change (l'archiviste a range quelque chose), on
# repart de zero. On ne peut donc pas servir les bouts d'une fiche pour une autre.
_BIBLIO2_BOUTS_CACHE = {}
_BIBLIO2_BOUTS_SIGNATURE = {"empreinte": None}


def _biblio2_bouts_de_fiche(cat, sous, fi):
    """v164 — LES BOUTS D'UNE FICHE (son etiquette courte, puis son texte coupe en morceaux de
    700 caracteres). EXACTEMENT ce que _biblio2_pertinences decoupait a chaque message, mais
    calcule UNE SEULE FOIS par fiche tant que l'arbre ne bouge pas : c'est le MEME decoupage, donc
    les memes empreintes et les memes scores -- rien ne change dans ce qui est choisi. C'est aussi
    ce que le fil de fond utilise pour PRE-CHAUFFER pendant les temps morts.

    POURQUOI CETTE CLE-LA : l'etiquette d'une fiche est faite de beaucoup de champs (rayon, tiroir,
    filtre, sous-filtre, resume, objet, qui, ou, type). Plutot que d'essayer de tous les resumer en
    une cle -- avec le risque de confondre deux fiches voisines -- on se repere sur la fiche
    elle-meme dans l'arbre charge, et on jette tout des que l'arbre a bouge. Ne leve jamais."""
    try:
        sig = _BIBLIO2_ARBRE_CACHE.get("empreinte")
        if sig != _BIBLIO2_BOUTS_SIGNATURE["empreinte"]:
            _BIBLIO2_BOUTS_CACHE.clear()
            _BIBLIO2_BOUTS_SIGNATURE["empreinte"] = sig
        cle = id(fi)
        garde = _BIBLIO2_BOUTS_CACHE.get(cle)
        # On garde AUSSI la fiche elle-meme a cote de ses bouts, et on verifie que c'est bien LA
        # MEME : tant qu'elle est gardee ici, Python ne peut pas donner son numero a une autre.
        # Impossible, donc, de servir les bouts d'une fiche pour une fiche voisine.
        if garde is not None and garde[0] is fi:
            return garde[1]
        texte = ((fi.get("resume") or "") + " " + (fi.get("texte") or "")).strip()
        etiq = _biblio2_etiquette(cat, sous, fi)
        # 13/10/2026, TRAVAIL 1 : c'etait « _decouper(texte)[:40] ». Une fiche de plus de
        # 28 000 caracteres n'etait donc mesuree QUE sur ses 28 000 premiers, et toute sa
        # fin devenait introuvable par le sens, en silence. Maintenant on elargit les
        # passages jusqu'a ce que tout rentre dans 40 : meme nombre de passages, donc meme
        # vitesse, et plus un seul caractere hors de la mesure.
        morceaux = _decouper_sans_rien_perdre(texte) or [texte or " "]
        bouts = (([etiq] if etiq else []) + morceaux, etiq, morceaux)
        _BIBLIO2_BOUTS_CACHE[cle] = (fi, bouts)
        return bouts
    except Exception:
        # au moindre doute : on refait le calcul sur place, sans rien garder
        try:
            texte = ((fi.get("resume") or "") + " " + (fi.get("texte") or "")).strip()
            etiq = _biblio2_etiquette(cat, sous, fi)
            morceaux = _decouper_sans_rien_perdre(texte) or [texte or " "]
            return (([etiq] if etiq else []) + morceaux, etiq, morceaux)
        except Exception:
            return ([" "], "", [" "])


